screenPanels.initJs:
function(container, apiUrl, tables) {
  let loginAttempts = 0;
  const maxAttempts = 5;
  let isAccountLocked = false;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラーメッセージ非表示関数
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // バリデーション関数
  function validateForm(userId, password) {
    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|'|"|;|--/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理関数
  async function handleLogin(userId, password, rememberLogin) {
    if (isAccountLocked) {
      showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
      return;
    }

    try {
      // ユーザーテーブルから認証情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました');
        return;
      }

      // ユーザー認証
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      // ここでは簡易的にプレーンテキストで比較
      if (user.パスワードハッシュ !== password) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // ログイン成功
      loginAttempts = 0; // リセット

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保持
      if (rememberLogin) {
        localStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      } else {
        sessionStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      }

      // 工数記録画面に遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('システムエラーが発生しました');
    }
  }

  // パスワード表示切り替え
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const passwordInput = container.querySelector('#password');
  let isPasswordVisible = false;

  togglePasswordBtn.addEventListener('click', () => {
    isPasswordVisible = !isPasswordVisible;
    passwordInput.type = isPasswordVisible ? 'text' : 'password';
    togglePasswordBtn.textContent = isPasswordVisible ? '🙈' : '👁️';
  });

  // ログインフォーム送信
  const loginForm = container.querySelector('#login-form');
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberLogin = container.querySelector('#remember-login').checked;

    if (!validateForm(userId, password)) {
      return;
    }

    await handleLogin(userId, password, rememberLogin);
  });

  // パスワード忘れリンク
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では別画面）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 既存のログイン状態をチェック
  const savedLogin = localStorage.getItem('loginUser') || sessionStorage.getItem('loginUser');
  if (savedLogin) {
    try {
      const loginData = JSON.parse(savedLogin);
      // 自動ログイン処理（工数記録画面に遷移）
      window.showScreen("scr-1778907133295");
    } catch (error) {
      // 無効なログインデータの場合はクリア
      localStorage.removeItem('loginUser');
      sessionStorage.removeItem('loginUser');
    }
  }

  // 入力フィールドにフォーカス
  container.querySelector('#user-id').focus();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let elapsedTimer = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let workState = 'stopped'; // 'stopped', 'working', 'paused'

  // DOM要素の取得
  const workerNameEl = container.querySelector('#worker-name');
  const currentDatetimeEl = container.querySelector('#current-datetime');
  const workItemSelect = container.querySelector('#work-item-select');
  const elapsedTimeEl = container.querySelector('#elapsed-time');
  const startBtn = container.querySelector('#start-btn');
  const pauseBtn = container.querySelector('#pause-btn');
  const endBtn = container.querySelector('#end-btn');
  const pauseReasonSection = container.querySelector('#pause-reason-section');
  const pauseReasonInput = container.querySelector('#pause-reason');
  const confirmPauseBtn = container.querySelector('#confirm-pause-btn');
  const cancelPauseBtn = container.querySelector('#cancel-pause-btn');
  const workMemoInput = container.querySelector('#work-memo');
  const memoCounter = container.querySelector('#memo-counter');
  const historyTbody = container.querySelector('#history-tbody');
  const saveBtn = container.querySelector('#save-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const errorMessage = container.querySelector('#error-message');

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 現在日時更新
  function updateCurrentDateTime() {
    const now = new Date();
    currentDatetimeEl.textContent = now.toLocaleString('ja-JP');
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (workState === 'paused' && pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    elapsedTimeEl.textContent = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  // 作業項目マスタ読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      if (workItems) {
        workItemSelect.innerHTML = '<option value="">選択してください</option>';
        workItems.filter(item => item.有効フラグ).forEach(item => {
          const option = document.createElement('option');
          option.value = item.id;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 本日の作業履歴描画
  function renderTodayHistory(records) {
    const today = new Date().toDateString();
    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toDateString();
      return recordDate === today;
    });

    historyTbody.innerHTML = todayRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workHours = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${String(record.作業時間 % 60).padStart(2, '0')}` : '';

      return `
        <tr data-id="${record.id}">
          <td>${startTime}</td>
          <td>${endTime}</td>
          <td>${record.作業内容 || ''}</td>
          <td>${workHours}</td>
          <td>${record.進捗状況 || ''}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${record.id}" style="font-size: 11px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${record.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録
      if (workRecords) {
        renderTodayHistory(workRecords);
      }
    } catch (error) {
      console.error('作業履歴の読み込みに失敗しました:', error);
    }
  }

  // 作業開始
  startBtn.addEventListener('click', () => {
    if (!workItemSelect.value) {
      showError('作業項目を選択してください');
      return;
    }

    startTime = new Date();
    totalPauseTime = 0;
    workState = 'working';

    startBtn.disabled = true;
    pauseBtn.disabled = false;
    endBtn.disabled = false;
    workItemSelect.disabled = true;

    elapsedTimer = setInterval(updateElapsedTime, 1000);
    updateElapsedTime();
  });

  // 作業中断
  pauseBtn.addEventListener('click', () => {
    if (workState !== 'working') {
      showError('作業が開始されていません');
      return;
    }

    pauseReasonSection.style.display = 'block';
    pauseReasonInput.focus();
  });

  // 中断確定
  confirmPauseBtn.addEventListener('click', async () => {
    if (!pauseReasonInput.value.trim()) {
      showError('中断理由を入力してください');
      return;
    }

    pauseStartTime = new Date();
    workState = 'paused';

    pauseBtn.textContent = '再開';
    pauseReasonSection.style.display = 'none';

    // 中断記録を保存
    try {
      await window.aivicApi.save(2, {
        作業記録ID: currentWorkRecord?.id || null,
        中断開始日時: pauseStartTime.toISOString(),
        中断理由区分: '作業中断',
        中断理由詳細: pauseReasonInput.value.trim(),
        対応状況: '対応中',
        記録者ID: 'current-user-id'
      });
      pauseReasonInput.value = '';
    } catch (error) {
      console.error('中断記録の保存に失敗しました:', error);
    }
  });

  // 中断キャンセル
  cancelPauseBtn.addEventListener('click', () => {
    pauseReasonSection.style.display = 'none';
    pauseReasonInput.value = '';
  });

  // 再開処理
  pauseBtn.addEventListener('click', () => {
    if (workState === 'paused') {
      const now = new Date();
      totalPauseTime += (now - pauseStartTime);
      pauseStartTime = null;
      workState = 'working';
      pauseBtn.textContent = '中断';
    }
  });

  // 作業終了
  endBtn.addEventListener('click', async () => {
    if (workState === 'stopped') {
      showError('作業が開始されていません');
      return;
    }

    const endTime = new Date();
    let workMinutes = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60));

    if (workState === 'paused' && pauseStartTime) {
      workMinutes = Math.floor((pauseStartTime - startTime - totalPauseTime) / (1000 * 60));
    }

    // 作業記録を保存
    try {
      const workRecord = await window.aivicApi.save(1, {
        作業員ID: 'current-user-id',
        作業日: startTime.toISOString(),
        作業開始時刻: startTime.toISOString(),
        作業終了時刻: endTime.toISOString(),
        作業時間: workMinutes,
        プロジェクト名: 'プロジェクト名',
        作業場所: '現場',
        作業種別: '一般作業',
        作業内容: workMemoInput.value || '作業完了',
        進捗状況: '完了',
        備考: workMemoInput.value,
        承認状態: '未承認',
        作成者ID: 'current-user-id'
      });

      if (workRecord) {
        // 状態リセット
        workState = 'stopped';
        startTime = null;
        totalPauseTime = 0;
        pauseStartTime = null;

        startBtn.disabled = false;
        pauseBtn.disabled = true;
        endBtn.disabled = true;
        workItemSelect.disabled = false;
        workItemSelect.value = '';
        workMemoInput.value = '';

        clearInterval(elapsedTimer);
        elapsedTimeEl.textContent = '00:00:00';

        // 履歴を再読み込み
        loadInitialData();
      }
    } catch (error) {
      console.error('作業記録の保存に失敗しました:', error);
      showError('作業記録の保存に失敗しました');
    }
  });

  // 保存ボタン
  saveBtn.addEventListener('click', async () => {
    if (workState !== 'stopped') {
      showError('作業を終了してから保存してください');
      return;
    }

    // 現在の状態を保存（メモなど）
    loadInitialData();
  });

  // キャンセルボタン
  cancelBtn.addEventListener('click', () => {
    if (workState !== 'stopped') {
      if (confirm('作業中ですが、本当にキャンセルしますか？入力した内容は保存されません。')) {
        // 作業状態をリセット
        workState = 'stopped';
        startTime = null;
        totalPauseTime = 0;
        pauseStartTime = null;

        startBtn.disabled = false;
        pauseBtn.disabled = true;
        endBtn.disabled = true;
        workItemSelect.disabled = false;
        workItemSelect.value = '';
        workMemoInput.value = '';

        clearInterval(elapsedTimer);
        elapsedTimeEl.textContent = '00:00:00';
        pauseReasonSection.style.display = 'none';
      }
    } else {
      workItemSelect.value = '';
      workMemoInput.value = '';
      memoCounter.textContent = '0';
    }
  });

  // メモ文字数カウンター
  workMemoInput.addEventListener('input', () => {
    memoCounter.textContent = workMemoInput.value.length;
  });

  // 中断理由文字数制限
  pauseReasonInput.addEventListener('input', () => {
    if (pauseReasonInput.value.length > 500) {
      pauseReasonInput.value = pauseReasonInput.value.substring(0, 500);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      try {
        await window.aivicApi.delete(1, deleteBtn.dataset.id);
        loadInitialData();
      } catch (error) {
        console.error('削除に失敗しました:', error);
        showError('削除に失敗しました');
      }
    }

    if (editBtn) {
      // 編集機能は簡易実装（実際のプロジェクトでは別画面に遷移）
      const recordId = editBtn.dataset.id;
      console.log('編集対象ID:', recordId);
    }
  });

  // 初期化処理
  updateCurrentDateTime();
  setInterval(updateCurrentDateTime, 1000);
  loadWorkItems();
  loadInitialData();

  // 初期データがある場合は即座に描画
  if (tables[1] && tables[1].records) {
    renderTodayHistory(tables[1].records);
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#work-history-tbody');
  const resultCount = container.querySelector('#result-count');
  const noResults = container.querySelector('#no-results');
  const errorMessage = container.querySelector('#error-message');
  const workItemSelect = container.querySelector('#select-work-item');
  const workerSelect = container.querySelector('#select-worker');

  let allWorkRecords = [];
  let allUsers = [];
  let allWorkItems = [];
  let allInterruptions = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // 日付フォーマット関数
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function formatTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function formatDuration(minutes) {
    if (!minutes) return '';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 中断回数を計算
  function getInterruptionCount(workRecordId) {
    return allInterruptions.filter(i => i.作業記録ID === workRecordId).length;
  }

  // 作業項目名を取得
  function getWorkItemName(workRecordId) {
    const workRecord = allWorkRecords.find(w => w.作業記録ID === workRecordId);
    if (!workRecord) return '';
    const workItem = allWorkItems.find(w => w.作業項目名 === workRecord.作業種別);
    return workItem ? workItem.作業項目名 : workRecord.作業種別 || '';
  }

  // 作業者名を取得
  function getWorkerName(userId) {
    const user = allUsers.find(u => u.ユーザーID === userId);
    return user ? user.氏名 : '';
  }

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    let bgColor, textColor;
    switch(status) {
      case '完了':
        bgColor = 'rgba(34, 197, 94, 0.2)';
        textColor = '#86efac';
        break;
      case '作業中':
        bgColor = 'rgba(59, 130, 246, 0.2)';
        textColor = '#93c5fd';
        break;
      case '中断':
        bgColor = 'rgba(245, 158, 11, 0.2)';
        textColor = '#fbbf24';
        break;
      default:
        bgColor = 'rgba(107, 114, 128, 0.2)';
        textColor = '#d1d5db';
    }
    return `<span style="background: ${bgColor}; color: ${textColor}; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      resultCount.textContent = '0件';
      noResults.classList.remove('hidden');
      return;
    }

    noResults.classList.add('hidden');
    resultCount.textContent = `${rows.length}件`;

    tbody.innerHTML = rows.map(record => {
      const interruptionCount = getInterruptionCount(record.作業記録ID);
      const workItemName = getWorkItemName(record.作業記録ID) || record.作業種別 || '';

      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px 10px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 8px 10px; color: var(--text);">${workItemName}</td>
          <td style="padding: 8px 10px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 8px 10px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 8px 10px; text-align: right; color: var(--text);">${formatDuration(record.作業時間)}</td>
          <td style="padding: 8px 10px; text-align: center; color: var(--text);">${interruptionCount}</td>
          <td style="padding: 8px 10px; text-align: center;">${getStatusBadge(record.進捗状況)}</td>
          <td style="padding: 8px 10px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // フィルター処理
  function applyFilters() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const workItem = container.querySelector('#select-work-item').value;
    const status = container.querySelector('#select-status').value;
    const worker = container.querySelector('#select-worker').value;

    // 日付バリデーション
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(23, 59, 59, 999);

      if (start > end) {
        showError('開始日は終了日より前の日付を入力してください');
        return;
      }

      if (start > today || end > today) {
        showError('未来の日付は選択できません');
        return;
      }

      const oneYearAgo = new Date();
      oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
      if (start < oneYearAgo) {
        showError('1年以上前の期間は選択できません');
        return;
      }
    }

    let filteredRecords = [...allWorkRecords];

    // 日付範囲フィルター
    if (startDate || endDate) {
      if (!startDate || !endDate) {
        showError('日付範囲を選択してください');
        return;
      }

      filteredRecords = filteredRecords.filter(record => {
        const workDate = new Date(record.作業日);
        const start = new Date(startDate);
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        return workDate >= start && workDate <= end;
      });
    }

    // 作業項目フィルター
    if (workItem) {
      filteredRecords = filteredRecords.filter(record => 
        record.作業種別 === workItem
      );
    }

    // 作業状況フィルター
    if (status) {
      filteredRecords = filteredRecords.filter(record => 
        record.進捗状況 === status
      );
    }

    // 作業者フィルター
    if (worker) {
      filteredRecords = filteredRecords.filter(record => 
        record.作業員ID === worker
      );
    }

    // 作業日の降順でソート
    filteredRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

    renderRows(filteredRecords);
  }

  // セレクトボックスの初期化
  function initializeSelects() {
    // 作業項目の選択肢を設定
    const workItemOptions = [...new Set(allWorkRecords.map(r => r.作業種別).filter(Boolean))];
    workItemSelect.innerHTML = '<option value="">すべて</option>' + 
      workItemOptions.map(item => `<option value="${item}">${item}</option>`).join('');

    // 作業者の選択肢を設定
    const workerOptions = allUsers.filter(u => 
      allWorkRecords.some(r => r.作業員ID === u.ユーザーID)
    );
    workerSelect.innerHTML = '<option value="">すべて</option>' + 
      workerOptions.map(user => `<option value="${user.ユーザーID}">${user.氏名}</option>`).join('');
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['作業日', '作業項目', '開始時刻', '終了時刻', '作業時間', '中断回数', '状況', '作業者', '作業場所', '作業内容'];
    const csvData = [headers];

    allWorkRecords.forEach(record => {
      const row = [
        formatDate(record.作業日),
        getWorkItemName(record.作業記録ID) || record.作業種別 || '',
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        formatDuration(record.作業時間),
        getInterruptionCount(record.作業記録ID),
        record.進捗状況 || '',
        getWorkerName(record.作業員ID),
        record.作業場所 || '',
        record.作業内容 || ''
      ];
      csvData.push(row);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(cell => `"${(cell || '').toString().replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      const [workRecords, users, workItems, interruptions] = await Promise.all([
        window.aivicApi.list(1), // 作業記録
        window.aivicApi.list(0), // ユーザー
        window.aivicApi.list(3), // 作業項目マスタ
        window.aivicApi.list(2)  // 中断記録
      ]);

      allWorkRecords = workRecords || tables[1]?.records || [];
      allUsers = users || tables[0]?.records || [];
      allWorkItems = workItems || tables[3]?.records || [];
      allInterruptions = interruptions || tables[2]?.records || [];

      initializeSelects();

      // 作業日の降順でソート
      const sortedRecords = [...allWorkRecords].sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
      renderRows(sortedRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // フォールバック: テーブルの初期データを使用
      allWorkRecords = tables[1]?.records || [];
      allUsers = tables[0]?.records || [];
      allWorkItems = tables[3]?.records || [];
      allInterruptions = tables[2]?.records || [];

      initializeSelects();
      const sortedRecords = [...allWorkRecords].sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
      renderRows(sortedRecords);
    }
  }

  // イベントリスナーの登録
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-work-item').value = '';
    container.querySelector('#select-status').value = '';
    container.querySelector('#select-worker').value = '';

    const sortedRecords = [...allWorkRecords].sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
    renderRows(sortedRecords);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      // 詳細確認画面に遷移（レコードIDをパラメータとして渡す）
      window.showScreen('scr-1778907367889', { recordId });
    }
  });

  // データ抽出ボタンの追加（ヘッダー部分に）
  const headerButtons = container.querySelector('div[style*="justify-content: space-between"] div');
  const extractBtn = document.createElement('button');
  extractBtn.className = 'action-btn';
  extractBtn.textContent = 'データ抽出';
  extractBtn.style.cssText = 'background: var(--primary); color: #fff; border: none; padding: 6px 14px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; margin-right: 8px;';
  extractBtn.addEventListener('click', () => {
    window.showScreen('scr-1778907353387');
  });
  headerButtons.insertBefore(extractBtn, headerButtons.firstChild);

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中 太郎' };
  let selectedResumeWorkId = null;

  // 現在日時更新
  function updateDateTime() {
    const now = new Date();
    const dateStr = now.getFullYear() + '/' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '/' + 
                   String(now.getDate()).padStart(2, '0') + ' ' +
                   String(now.getHours()).padStart(2, '0') + ':' + 
                   String(now.getMinutes()).padStart(2, '0');
    container.querySelector('[data-testid="current-datetime"]').textContent = dateStr;
  }

  // 作業項目選択肢を読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">-- 作業項目を選択 --</option>';

    if (workItems) {
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 進行中作業一覧を描画
  function renderActiveWorks(works) {
    const container_el = container.querySelector('#active-works-list');
    if (!works || works.length === 0) {
      container_el.innerHTML = '<div class="no-active-works" style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 12px;">進行中の作業はありません</div>';
      return;
    }

    container_el.innerHTML = works.map(work => {
      const startTime = new Date(work.作業開始時刻);
      const elapsed = Math.floor((Date.now() - startTime.getTime()) / 60000);
      const elapsedStr = elapsed < 60 ? `${elapsed}分` : `${Math.floor(elapsed/60)}時間${elapsed%60}分`;

      return `
        <div class="work-item" style="padding: 8px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 8px; border-left: 3px solid var(--primary);">
          <div style="font-size: 13px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${work.プロジェクト名}</div>
          <div style="font-size: 11px; color: var(--text-muted);">
            開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')} | 
            経過: ${elapsedStr}
          </div>
          ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所}</div>` : ''}
        </div>
      `;
    }).join('');
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks(works) {
    const container_el = container.querySelector('#suspended-works-list');
    if (!works || works.length === 0) {
      container_el.innerHTML = '<div class="no-suspended-works" style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 12px;">中断中の作業はありません</div>';
      return;
    }

    container_el.innerHTML = works.map(work => {
      const startTime = new Date(work.作業開始時刻);
      return `
        <div class="work-item" style="padding: 8px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 8px; border-left: 3px solid #ff9500;">
          <div style="font-size: 13px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${work.プロジェクト名}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
            開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')}
          </div>
          ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">場所: ${work.作業場所}</div>` : ''}
          <button class="action-btn resume-btn" data-id="${work.作業記録ID}" style="background: #ff9500; color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">再開</button>
        </div>
      `;
    }).join('');
  }

  // 作業状況を読み込み
  async function loadWorkStatus() {
    const workRecords = await window.aivicApi.list(1); // 作業記録
    if (!workRecords) return;

    const activeWorks = workRecords.filter(work => 
      work.作業員ID === currentUser.id && work.進捗状況 === '作業中'
    );

    const suspendedWorks = workRecords.filter(work => 
      work.作業員ID === currentUser.id && work.進捗状況 === '中断'
    );

    renderActiveWorks(activeWorks);
    renderSuspendedWorks(suspendedWorks);
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.style.display = 'block';
    setTimeout(() => {
      errorEl.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workItemId = container.querySelector('#work-item-select').value;
    const location = container.querySelector('#work-location-input').value.trim();
    const notes = container.querySelector('#work-notes-input').value.trim();

    if (!workItemId) {
      showError('作業項目を選択してください');
      return false;
    }

    if (location.length > 100) {
      showError('作業場所は100文字以内で入力してください');
      return false;
    }

    if (notes.length > 500) {
      showError('備考は500文字以内で入力してください');
      return false;
    }

    // XSS対策の簡易チェック
    if (location.includes('<script>') || notes.includes('<script>')) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 複数作業同時開始チェック
  async function checkActiveWorks() {
    const workRecords = await window.aivicApi.list(1);
    if (!workRecords) return true;

    const activeWorks = workRecords.filter(work => 
      work.作業員ID === currentUser.id && work.進捗状況 === '作業中'
    );

    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return false;
    }

    return true;
  }

  // 作業開始処理
  async function startWork() {
    if (!validateForm()) return;
    if (!await checkActiveWorks()) return;

    const workItemId = container.querySelector('#work-item-select').value;
    const location = container.querySelector('#work-location-input').value.trim();
    const notes = container.querySelector('#work-notes-input').value.trim();

    // 作業項目情報を取得
    const workItems = await window.aivicApi.list(3);
    const selectedWorkItem = workItems?.find(item => item.作業項目ID === workItemId);

    if (!selectedWorkItem) {
      showError('選択された作業項目が見つかりません');
      return;
    }

    const workRecord = {
      作業員ID: currentUser.id,
      作業日: new Date().toISOString().split('T')[0],
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: selectedWorkItem.作業項目名,
      作業場所: location || '',
      作業種別: selectedWorkItem.カテゴリ || '一般作業',
      作業内容: notes || '',
      進捗状況: '作業中',
      備考: notes || '',
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location-input').value = '';
      container.querySelector('#work-notes-input').value = '';
      container.querySelector('.char-counter').textContent = '0/500';

      // 作業状況を更新
      await loadWorkStatus();

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");
    }
  }

  // 作業再開処理
  async function resumeWork(workId) {
    const workRecords = await window.aivicApi.list(1);
    const work = workRecords?.find(w => w.作業記録ID === workId);

    if (!work) {
      showError('指定された作業が見つかりません');
      return;
    }

    if (!await checkActiveWorks()) return;

    const updated = await window.aivicApi.update(1, workId, {
      進捗状況: '作業中',
      更新日時: new Date().toISOString()
    });

    if (updated) {
      await loadWorkStatus();
      // モーダルを閉じる
      container.querySelector('#resume-modal').style.display = 'none';

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");
    }
  }

  // 文字数カウンター更新
  function updateCharCounter() {
    const textarea = container.querySelector('#work-notes-input');
    const counter = container.querySelector('.char-counter');
    counter.textContent = `${textarea.value.length}/500`;
  }

  // 初期化
  updateDateTime();
  setInterval(updateDateTime, 60000); // 1分ごとに更新

  loadWorkItems();
  loadWorkStatus();

  // イベントリスナー
  container.querySelector('#start-work-button').addEventListener('click', startWork);

  container.querySelector('#work-notes-input').addEventListener('input', updateCharCounter);

  // 設定ボタン
  container.querySelector('[data-testid="settings-button"]').addEventListener('click', () => {
    // 設定画面への遷移（実装されていない場合の仮処理）
    alert('設定画面は準備中です');
  });

  // ログアウトボタン
  container.querySelector('[data-testid="logout-button"]').addEventListener('click', () => {
    if (confirm('ログアウトしますか？')) {
      window.location.href = './login.html';
    }
  });

  // 再開ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      selectedResumeWorkId = resumeBtn.dataset.id;
      container.querySelector('#resume-modal').style.display = 'block';
    }
  });

  // モーダルイベント
  container.querySelector('#resume-confirm-btn').addEventListener('click', () => {
    if (selectedResumeWorkId) {
      resumeWork(selectedResumeWorkId);
    }
  });

  container.querySelector('#resume-cancel-btn').addEventListener('click', () => {
    container.querySelector('#resume-modal').style.display = 'none';
    selectedResumeWorkId = null;
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#resume-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#resume-modal')) {
      container.querySelector('#resume-modal').style.display = 'none';
      selectedResumeWorkId = null;
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の作業記録データを取得（最新の未完了記録を想定）
  let currentRecord = null;

  // 初期データの設定
  function initializeData() {
    const workRecords = tables[1].records || []; // 作業記録テーブル
    const breakRecords = tables[2].records || []; // 中断記録テーブル

    // 最新の未完了作業記録を取得
    currentRecord = workRecords.find(r => !r.作業終了時刻) || workRecords[0];

    if (currentRecord) {
      // 作業項目名を表示
      container.querySelector('#work-item').textContent = currentRecord.作業内容 || '作業項目未設定';
      container.querySelector('#record-id').textContent = currentRecord.作業記録ID || 'WR-2024-001';

      // 時刻情報を表示
      const startTime = currentRecord.作業開始時刻 ? new Date(currentRecord.作業開始時刻) : new Date();
      const endTime = new Date(); // 現在時刻を終了時刻とする

      container.querySelector('#start-time').textContent = formatTime(startTime);
      container.querySelector('#end-time').textContent = formatTime(endTime);

      // 作業時間計算
      const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));

      // 中断時間計算
      const relatedBreaks = breakRecords.filter(b => b.作業記録ID === currentRecord.作業記録ID);
      const breakMinutes = relatedBreaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);

      // 実作業時間計算
      const actualMinutes = totalMinutes - breakMinutes;

      container.querySelector('#total-time').textContent = formatDuration(totalMinutes);
      container.querySelector('#break-time').textContent = formatDuration(breakMinutes);
      container.querySelector('#actual-work-time').textContent = formatDuration(actualMinutes);
    }
  }

  // 時刻フォーマット関数
  function formatTime(date) {
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 時間フォーマット関数
  function formatDuration(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション関数
  function validateForm() {
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueDetail = container.querySelector('#issue-detail').value.trim();
    const workMemo = container.querySelector('#work-memo').value.trim();

    // 完了状況必須チェック
    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    // 異常報告チェック時の異常内容必須チェック
    if (hasIssue && !issueDetail) {
      showError('異常報告をチェックした場合は、異常内容を入力してください。');
      return false;
    }

    // 文字数制限チェック
    if (workMemo.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueDetail.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 文字数カウンター更新
  function updateCharCount(inputId, countId) {
    const input = container.querySelector(`#${inputId}`);
    const counter = container.querySelector(`#${countId}`);
    if (input && counter) {
      counter.textContent = input.value.length;
    }
  }

  // 初期化
  initializeData();

  // 異常報告チェックボックスの制御
  container.querySelector('#has-issue').addEventListener('change', function() {
    const issueSection = container.querySelector('#issue-detail-section');
    const issueDetail = container.querySelector('#issue-detail');

    if (this.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      issueDetail.value = ''; // 内容をクリア
      updateCharCount('issue-detail', 'issue-count');
    }
  });

  // 文字数カウンター
  container.querySelector('#work-memo').addEventListener('input', function() {
    updateCharCount('work-memo', 'memo-count');
  });

  container.querySelector('#issue-detail').addEventListener('input', function() {
    updateCharCount('issue-detail', 'issue-count');
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!validateForm()) return;

    const completionStatus = container.querySelector('#completion-status').value;
    const workMemo = container.querySelector('#work-memo').value.trim();
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueDetail = container.querySelector('#issue-detail').value.trim();

    try {
      // 作業記録を更新
      const endTime = new Date().toISOString();
      const startTime = currentRecord ? new Date(currentRecord.作業開始時刻).getTime() : Date.now();
      const workMinutes = Math.floor((Date.now() - startTime) / (1000 * 60));

      const updateData = {
        作業終了時刻: endTime,
        作業時間: workMinutes,
        進捗状況: completionStatus,
        備考: workMemo || null,
        承認状態: '未承認'
      };

      const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue && issueDetail) {
          await window.aivicApi.save(4, {
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentRecord.作業記録ID,
            ユーザーID: currentRecord.作業員ID,
            異常値種別: '作業異常報告',
            検出項目: '異常内容',
            検出値: issueDetail,
            閾値: '手動報告',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString()
          });
        }

        alert('工数記録が正常に確定されました。');
        // 記録確認画面に遷移
        window.showScreen("scr-1778907226171");
      } else {
        showError('記録の保存に失敗しました。もう一度お試しください。');
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の保存中にエラーが発生しました。');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('入力内容が破棄されますが、よろしいですか？')) {
      history.back(); // 前画面に戻る
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-check-record').addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // ホバー効果
  const buttons = container.querySelectorAll('button');
  buttons.forEach(btn => {
    if (btn.classList.contains('action-btn') && !btn.classList.contains('secondary')) {
      btn.addEventListener('mouseenter', function() {
        this.style.background = 'var(--primary-hover)';
      });
      btn.addEventListener('mouseleave', function() {
        this.style.background = 'var(--primary)';
      });
    } else if (btn.classList.contains('secondary')) {
      btn.addEventListener('mouseenter', function() {
        this.style.background = 'rgba(255,255,255,0.05)';
      });
      btn.addEventListener('mouseleave', function() {
        this.style.background = 'transparent';
      });
    }
  });
}

function(container, apiUrl, tables) {
  // 自動保存の状態管理
  let autoSaveInterval = null;
  let saveIntervalSeconds = 30;
  let isOnline = navigator.onLine;
  let pendingData = [];
  let localStorageKey = 'workRecordAutoSave';

  // DOM要素の取得
  const autoSaveStatus = container.querySelector('#auto-save-status');
  const autoSaveIndicator = container.querySelector('#auto-save-indicator');
  const networkStatus = container.querySelector('#network-status');
  const networkIndicator = container.querySelector('#network-indicator');
  const pendingCountEl = container.querySelector('#pending-count');
  const lastSaveTimeEl = container.querySelector('#last-save-time');
  const saveIntervalInput = container.querySelector('#save-interval');
  const localDataTbody = container.querySelector('#local-data-tbody');
  const errorNotification = container.querySelector('#error-notification');
  const errorMessage = container.querySelector('#error-message');
  const recoverableCountEl = container.querySelector('#recoverable-count');
  const lastBackupTimeEl = container.querySelector('#last-backup-time');
  const recoveryDialog = container.querySelector('#recovery-dialog');
  const recoveryPreview = container.querySelector('#recovery-preview');

  // ローカルストレージからデータを取得
  function getLocalData() {
    try {
      const data = localStorage.getItem(localStorageKey);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('ローカルデータの取得に失敗:', e);
      return [];
    }
  }

  // ローカルストレージにデータを保存
  function saveLocalData(data) {
    try {
      localStorage.setItem(localStorageKey, JSON.stringify(data));
      return true;
    } catch (e) {
      console.error('ローカルデータの保存に失敗:', e);
      showError('ストレージ容量不足のため保存に失敗しました。不要なデータを削除してください。');
      return false;
    }
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorNotification.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    errorNotification.classList.add('hidden');
  }

  // ネットワーク状態の更新
  function updateNetworkStatus() {
    isOnline = navigator.onLine;
    networkStatus.textContent = isOnline ? 'オンライン' : 'オフライン';
    networkIndicator.style.background = isOnline ? '#22c55e' : '#ef4444';

    if (isOnline && pendingData.length > 0) {
      // オンライン復旧時の自動同期
      setTimeout(() => syncPendingData(), 1000);
    }
  }

  // 同期待ちデータの更新
  function updatePendingCount() {
    pendingData = getLocalData().filter(item => !item.synced);
    pendingCountEl.textContent = pendingData.length;

    // 上限チェック（100件）
    if (pendingData.length >= 100) {
      showError('同期待ちデータが上限（100件）に達しました。手動同期を実行してください。');
    }
  }

  // 最終保存時刻の更新
  function updateLastSaveTime() {
    const now = new Date();
    lastSaveTimeEl.textContent = now.toLocaleTimeString('ja-JP', { 
      hour: '2-digit', 
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // ローカルデータ一覧の描画
  function renderLocalData() {
    const localData = getLocalData();

    if (localData.length === 0) {
      localDataTbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); padding: 20px;">ローカルデータはありません</td></tr>';
      return;
    }

    localDataTbody.innerHTML = localData.map(item => `
      <tr data-id="${item.id}">
        <td>${new Date(item.timestamp).toLocaleString('ja-JP')}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${item.content || '作業記録'}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
                       background: ${item.synced ? '#22c55e' : '#f59e0b'}; color: #fff;">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td>${Math.round(JSON.stringify(item).length / 1024 * 100) / 100} KB</td>
        <td>
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 自動保存の実行
  async function performAutoSave() {
    try {
      // 現在の入力データを取得（実際の実装では工数記録画面から取得）
      const currentData = {
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        content: '自動保存データ',
        workDate: new Date().toISOString().split('T')[0],
        startTime: new Date().toISOString(),
        projectName: 'サンプルプロジェクト',
        workType: '作業',
        workContent: '自動保存されたデータ',
        status: '作業中',
        synced: false
      };

      const localData = getLocalData();

      // 上限チェック
      if (localData.length >= 100) {
        showError('ローカルストレージの上限に達しました。');
        return;
      }

      localData.push(currentData);

      if (saveLocalData(localData)) {
        updateLastSaveTime();
        updatePendingCount();
        renderLocalData();

        // オンライン時はサーバー同期を試行
        if (isOnline) {
          await syncDataToServer(currentData);
        }
      }
    } catch (error) {
      console.error('自動保存エラー:', error);
      showError('自動保存に失敗しました: ' + error.message);
    }
  }

  // サーバーとの同期
  async function syncDataToServer(data) {
    try {
      const saved = await window.aivicApi.save(1, {
        作業員ID: 'user-001',
        作業日: data.workDate,
        作業開始時刻: data.startTime,
        プロジェクト名: data.projectName,
        作業種別: data.workType,
        作業内容: data.workContent,
        進捗状況: data.status,
        承認状態: '未承認',
        作成者ID: 'user-001'
      });

      if (saved) {
        // 同期成功時はローカルデータを更新
        const localData = getLocalData();
        const index = localData.findIndex(item => item.id === data.id);
        if (index !== -1) {
          localData[index].synced = true;
          saveLocalData(localData);
          updatePendingCount();
          renderLocalData();
        }
      }
    } catch (error) {
      console.error('サーバー同期エラー:', error);
      showError('サーバーとの同期に失敗しました: ' + error.message);
    }
  }

  // 未同期データの一括同期
  async function syncPendingData() {
    const unsyncedData = getLocalData().filter(item => !item.synced);

    if (unsyncedData.length === 0) {
      return;
    }

    let successCount = 0;
    let failCount = 0;

    for (const data of unsyncedData) {
      try {
        await syncDataToServer(data);
        successCount++;
      } catch (error) {
        failCount++;
      }
    }

    if (failCount > 0) {
      showError(`同期完了: 成功${successCount}件、失敗${failCount}件`);
    }
  }

  // 自動保存の開始
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(performAutoSave, saveIntervalSeconds * 1000);
    autoSaveStatus.textContent = '有効';
    autoSaveIndicator.style.background = '#22c55e';
  }

  // 自動保存の停止
  function stopAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
      autoSaveInterval = null;
    }
    autoSaveStatus.textContent = '無効';
    autoSaveIndicator.style.background = '#ef4444';
  }

  // 復旧可能データの更新
  function updateRecoverableData() {
    const localData = getLocalData();
    const recoverableData = localData.filter(item => !item.synced);
    recoverableCountEl.textContent = `${recoverableData.length}件`;

    if (recoverableData.length > 0) {
      const lastData = recoverableData[recoverableData.length - 1];
      lastBackupTimeEl.textContent = new Date(lastData.timestamp).toLocaleTimeString('ja-JP');
    } else {
      lastBackupTimeEl.textContent = '--:--';
    }
  }

  // データ復旧ダイアログの表示
  function showRecoveryDialog() {
    const recoverableData = getLocalData().filter(item => !item.synced);

    if (recoverableData.length === 0) {
      showError('復旧可能なデータがありません。');
      return;
    }

    recoveryPreview.innerHTML = recoverableData.map(item => `
      <div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.1); font-size: 12px;">
        <div style="font-weight: 500; color: var(--text);">${new Date(item.timestamp).toLocaleString('ja-JP')}</div>
        <div style="color: var(--text-muted); margin-top: 2px;">${item.content}</div>
      </div>
    `).join('');

    recoveryDialog.classList.remove('hidden');
  }

  // イベントリスナーの設定

  // 保存間隔の適用
  container.querySelector('#btn-apply-interval').addEventListener('click', () => {
    const newInterval = parseInt(saveIntervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください。');
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒（24時間）以下で設定してください。');
      return;
    }

    saveIntervalSeconds = newInterval;
    startAutoSave();
    hideError();
  });

  // 手動同期
  container.querySelector('#btn-manual-sync').addEventListener('click', async () => {
    if (!isOnline) {
      showError('オフライン状態では同期できません。');
      return;
    }

    await syncPendingData();
  });

  // 強制保存
  container.querySelector('#btn-force-save').addEventListener('click', () => {
    performAutoSave();
  });

  // ローカルデータクリア
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('すべてのローカルデータを削除しますか？未同期のデータは失われます。')) {
      localStorage.removeItem(localStorageKey);
      renderLocalData();
      updatePendingCount();
      updateRecoverableData();
    }
  });

  // ローカルデータ更新
  container.querySelector('#btn-refresh-local').addEventListener('click', () => {
    renderLocalData();
    updatePendingCount();
    updateRecoverableData();
  });

  // データ復旧
  container.querySelector('#btn-recover-data').addEventListener('click', () => {
    showRecoveryDialog();
  });

  // 復旧ダイアログのキャンセル
  container.querySelector('#btn-cancel-recovery').addEventListener('click', () => {
    recoveryDialog.classList.add('hidden');
  });

  // 復旧実行
  container.querySelector('#btn-confirm-recovery').addEventListener('click', () => {
    // 実際の復旧処理（工数記録画面にデータを復元）
    recoveryDialog.classList.add('hidden');
    window.showScreen('scr-1778907133295'); // 工数記録画面に戻る
  });

  // エラー再試行
  container.querySelector('#btn-retry').addEventListener('click', () => {
    hideError();
    if (isOnline) {
      syncPendingData();
    } else {
      performAutoSave();
    }
  });

  // ローカルデータの個別削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (confirm('このローカルデータを削除しますか？')) {
        const localData = getLocalData();
        const filteredData = localData.filter(item => item.id !== id);
        saveLocalData(filteredData);
        renderLocalData();
        updatePendingCount();
        updateRecoverableData();
      }
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 初期化
  updateNetworkStatus();
  updatePendingCount();
  renderLocalData();
  updateRecoverableData();
  startAutoSave();

  // ページ離脱時の自動保存
  window.addEventListener('beforeunload', () => {
    performAutoSave();
  });
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let isRecording = false;
  let currentAudioBlob = null;

  // DOM要素の取得
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#reason');
  const locationInput = container.querySelector('#location');
  const detailsTextarea = container.querySelector('#details');
  const charCount = container.querySelector('#char-count');
  const durationDisplay = container.querySelector('#duration-display');
  const photoInput = container.querySelector('#photo-input');
  const photoBtn = container.querySelector('#photo-btn');
  const photoName = container.querySelector('#photo-name');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const recordStatus = container.querySelector('#record-status');
  const audioPreview = container.querySelector('#audio-preview');
  const selectAllImpact = container.querySelector('#select-all-impact');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
  const relatedWork = container.querySelector('#related-work');
  const errorMessage = container.querySelector('#error-message');
  const tempSaveBtn = container.querySelector('#btn-temp-save');
  const completeBtn = container.querySelector('#btn-complete');

  // 現在時刻を初期値として設定
  const now = new Date();
  now.setSeconds(0, 0);
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    const count = detailsTextarea.value.length;
    charCount.textContent = `${count}/1000`;
    if (count > 1000) {
      charCount.style.color = '#fca5a5';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  });

  // 中断時間の自動計算
  function updateDuration() {
    const start = startTimeInput.value;
    const end = endTimeInput.value;

    if (start && end) {
      const startDate = new Date(start);
      const endDate = new Date(end);
      const diffMs = endDate - startDate;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDisplay.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
      } else {
        durationDisplay.textContent = '--:--';
      }
    } else {
      durationDisplay.textContent = '--:--';
    }
  }

  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);

  // 写真添付
  photoBtn.addEventListener('click', () => {
    photoInput.click();
  });

  photoInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // ファイルサイズチェック (10MB)
    if (file.size > 10 * 1024 * 1024) {
      showError('ファイルサイズは10MB以下にしてください');
      return;
    }

    // ファイル形式チェック
    if (!file.type.startsWith('image/')) {
      showError('画像ファイルのみ添付可能です');
      return;
    }

    photoName.textContent = file.name;

    // プレビュー表示
    const reader = new FileReader();
    reader.onload = (e) => {
      photoPreview.innerHTML = `<img src="${e.target.result}" style="max-width: 200px; max-height: 150px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);">`;
    };
    reader.readAsDataURL(file);
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          currentAudioBlob = new Blob(audioChunks, { type: 'audio/wav' });
          const audioUrl = URL.createObjectURL(currentAudioBlob);
          audioPreview.src = audioUrl;
          audioPreview.style.display = 'block';
          stream.getTracks().forEach(track => track.stop());
        };

        mediaRecorder.start();
        isRecording = true;
        recordBtn.textContent = '⏹️ 録音停止';
        recordStatus.textContent = '録音中...';
      } catch (error) {
        showError('マイクへのアクセスが拒否されました。録音機能を使用するには、マイクの使用を許可してください。');
      }
    } else {
      mediaRecorder.stop();
      isRecording = false;
      recordBtn.textContent = '🎤 録音開始';
      recordStatus.textContent = '録音完了';
    }
  });

  // 影響範囲の全選択・全解除
  selectAllImpact.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllImpact.checked;
    });
  });

  // 個別選択時の全選択チェックボックス連動
  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const allChecked = Array.from(impactCheckboxes).every(cb => cb.checked);
      const noneChecked = Array.from(impactCheckboxes).every(cb => !cb.checked);

      if (allChecked) {
        selectAllImpact.checked = true;
        selectAllImpact.indeterminate = false;
      } else if (noneChecked) {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = false;
      } else {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = true;
      }
    });
  });

  // 関連作業項目の表示（現在進行中の作業を取得）
  async function loadRelatedWork() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        const activeWork = workRecords.find(record => record.進捗状況 === '作業中');
        if (activeWork) {
          relatedWork.textContent = `${activeWork.プロジェクト名} - ${activeWork.作業種別}`;
        }
      }
    } catch (error) {
      console.error('関連作業項目の取得に失敗:', error);
    }
  }

  loadRelatedWork();

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    // 必須項目チェック
    if (!startTimeInput.value) {
      errors.push('中断開始時刻は必須です');
    }
    if (!reasonSelect.value) {
      errors.push('中断理由は必須です');
    }

    // 未来時刻チェック
    if (startTimeInput.value) {
      const startDate = new Date(startTimeInput.value);
      const now = new Date();
      if (startDate > now) {
        errors.push('中断開始時刻に未来の時刻は入力できません');
      }
    }

    if (endTimeInput.value) {
      const endDate = new Date(endTimeInput.value);
      const now = new Date();
      if (endDate > now) {
        errors.push('中断終了時刻に未来の時刻は入力できません');
      }
    }

    // 時刻の前後関係チェック
    if (startTimeInput.value && endTimeInput.value) {
      const startDate = new Date(startTimeInput.value);
      const endDate = new Date(endTimeInput.value);
      if (endDate <= startDate) {
        errors.push('中断終了時刻は開始時刻より後の時刻を入力してください');
      }
    }

    // 文字数チェック
    if (detailsTextarea.value.length > 1000) {
      errors.push('中断詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactValues = Array.from(container.querySelectorAll('input[name="impact"]:checked')).map(cb => cb.value);

    // 中断時間計算（分単位）
    let interruptionTime = null;
    if (startTimeInput.value && endTimeInput.value) {
      const startDate = new Date(startTimeInput.value);
      const endDate = new Date(endTimeInput.value);
      const diffMs = endDate - startDate;
      if (diffMs > 0) {
        interruptionTime = Math.floor(diffMs / (1000 * 60));
      }
    }

    return {
      中断開始日時: startTimeInput.value ? new Date(startTimeInput.value).toISOString() : null,
      中断終了日時: endTimeInput.value ? new Date(endTimeInput.value).toISOString() : null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value,
      中断時間: interruptionTime,
      影響度: urgencyRadio ? urgencyRadio.value : null,
      対応状況: '対応中',
      作業記録ID: 'temp-work-id', // 実際の実装では関連する作業記録IDを設定
      記録者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを設定
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', async () => {
    try {
      const formData = collectFormData();

      // ローカルストレージに保存
      localStorage.setItem('interruptionDraft', JSON.stringify({
        ...formData,
        影響範囲: Array.from(container.querySelectorAll('input[name="impact"]:checked')).map(cb => cb.value),
        中断場所: locationInput.value,
        写真ファイル名: photoName.textContent,
        音声メモ有無: currentAudioBlob ? true : false
      }));

      // 成功メッセージ
      const successMsg = container.querySelector('#error-message');
      successMsg.style.background = 'rgba(34, 197, 94, 0.1)';
      successMsg.style.borderColor = 'rgba(34, 197, 94, 0.3)';
      successMsg.style.color = '#86efac';
      successMsg.textContent = '一時保存しました';
      successMsg.style.display = 'block';

      setTimeout(() => {
        successMsg.style.display = 'none';
        successMsg.style.background = 'rgba(220, 38, 38, 0.1)';
        successMsg.style.borderColor = 'rgba(220, 38, 38, 0.3)';
        successMsg.style.color = '#fca5a5';
      }, 3000);

    } catch (error) {
      showError('一時保存に失敗しました');
    }
  });

  // 記録完了
  completeBtn.addEventListener('click', async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    try {
      const formData = collectFormData();
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruptionDraft');

        // 作業再開記録画面に遷移
        window.showScreen("scr-1778907251446");
      } else {
        showError('記録の保存に失敗しました');
      }
    } catch (error) {
      if (navigator.onLine === false) {
        showError('ネットワークに接続できません。接続を確認してから再度お試しください。');
      } else {
        showError('記録の保存中にエラーが発生しました');
      }
    }
  });

  // 一時保存データの復元
  function restoreDraft() {
    const draft = localStorage.getItem('interruptionDraft');
    if (draft) {
      try {
        const data = JSON.parse(draft);

        if (data.中断開始日時) {
          startTimeInput.value = new Date(data.中断開始日時).toISOString().slice(0, 16);
        }
        if (data.中断終了日時) {
          endTimeInput.value = new Date(data.中断終了日時).toISOString().slice(0, 16);
        }
        if (data.中断理由区分) {
          reasonSelect.value = data.中断理由区分;
        }
        if (data.中断理由詳細) {
          detailsTextarea.value = data.中断理由詳細;
          detailsTextarea.dispatchEvent(new Event('input'));
        }
        if (data.中断場所) {
          locationInput.value = data.中断場所;
        }
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        if (data.影響範囲 && Array.isArray(data.影響範囲)) {
          data.影響範囲.forEach(value => {
            const checkbox = container.querySelector(`input[name="impact"][value="${value}"]`);
            if (checkbox) checkbox.checked = true;
          });
          // 全選択チェックボックスの状態更新
          impactCheckboxes[0].dispatchEvent(new Event('change'));
        }

        updateDuration();
      } catch (error) {
        console.error('一時保存データの復元に失敗:', error);
      }
    }
  }

  // 初期化時に一時保存データを復元
  restoreDraft();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // 中断中作業一覧の再描画
  function renderSuspendedWorks(workRecords, interruptRecords) {
    const tbody = container.querySelector('#suspended-work-tbody');
    const noWorkDiv = container.querySelector('#no-suspended-work');

    // 中断中の作業を抽出（進捗状況が「中断」で、対応する中断記録が未終了）
    const suspendedWorks = workRecords.filter(work => 
      work.進捗状況 === '中断' && 
      interruptRecords.some(interrupt => 
        interrupt.作業記録ID === work.作業記録ID && !interrupt.中断終了日時
      )
    );

    if (suspendedWorks.length === 0) {
      tbody.innerHTML = '';
      noWorkDiv.classList.remove('hidden');
      container.querySelector('.table-wrap').classList.add('hidden');
      return;
    }

    noWorkDiv.classList.add('hidden');
    container.querySelector('.table-wrap').classList.remove('hidden');

    tbody.innerHTML = suspendedWorks.map(work => {
      const interrupt = interruptRecords.find(i => 
        i.作業記録ID === work.作業記録ID && !i.中断終了日時
      );

      const suspendTime = interrupt ? new Date(interrupt.中断開始日時).toLocaleString('ja-JP') : '-';
      const suspendReason = interrupt ? (interrupt.中断理由詳細 || interrupt.中断理由区分 || '-') : '-';

      return `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || work.プロジェクト名 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${suspendReason}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn select-work-btn" data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="font-size: 12px; padding: 4px 8px;">選択</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const timeInput = container.querySelector('#resume-time');
    timeInput.value = now.toISOString().slice(0, 16);
  }

  // 選択した作業の詳細を表示
  function showWorkDetails(workRecord, interruptRecord) {
    selectedWorkRecord = workRecord;
    selectedInterruptRecord = interruptRecord;

    const nameDiv = container.querySelector('#selected-work-name');
    const detailsDiv = container.querySelector('#selected-work-details');
    const resumeForm = container.querySelector('#resume-form');

    nameDiv.textContent = workRecord.作業内容 || workRecord.プロジェクト名 || '作業項目';
    detailsDiv.textContent = `プロジェクト: ${workRecord.プロジェクト名 || '-'} | 場所: ${workRecord.作業場所 || '-'}`;

    setCurrentTime();
    resumeForm.classList.remove('hidden');
  }

  // 文字数カウンター更新
  function updateCharCount() {
    const textarea = container.querySelector('#resume-reason-detail');
    const counter = container.querySelector('#char-count');
    counter.textContent = textarea.value.length;
  }

  // バリデーション
  function validateForm() {
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();
    const errorDiv = container.querySelector('#reason-error');

    if (!reasonDetail) {
      errorDiv.textContent = '再開理由の詳細は必須です';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (reasonDetail.length > 500) {
      errorDiv.textContent = '再開理由は500文字以内で入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    errorDiv.classList.add('hidden');
    return true;
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !selectedInterruptRecord) return;

    if (!validateForm()) return;

    const resumeTime = container.querySelector('#resume-time').value;
    const reasonSelect = container.querySelector('#resume-reason-select').value;
    const reasonDetail = container.querySelector('#resume-reason-detail').value.trim();

    try {
      // 中断記録を終了
      const updatedInterrupt = await window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
        中断終了日時: new Date(resumeTime).toISOString(),
        中断時間: Math.floor((new Date(resumeTime) - new Date(selectedInterruptRecord.中断開始日時)) / 60000),
        対応状況: '解決済み'
      });

      if (!updatedInterrupt) {
        alert('中断記録の更新に失敗しました');
        return;
      }

      // 作業記録を作業中に更新
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        備考: `${selectedWorkRecord.備考 || ''}\n[再開] ${new Date(resumeTime).toLocaleString('ja-JP')}: ${reasonSelect || ''}${reasonDetail ? ' - ' + reasonDetail : ''}`.trim()
      });

      if (!updatedWork) {
        alert('作業記録の更新に失敗しました');
        return;
      }

      alert('作業を再開しました');

      // 画面をリセット
      container.querySelector('#resume-form').classList.add('hidden');
      selectedWorkRecord = null;
      selectedInterruptRecord = null;

      // 一覧を再読み込み
      loadData();

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");

    } catch (error) {
      console.error('作業再開エラー:', error);
      alert('作業再開に失敗しました');
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      const [workRecords, interruptRecords] = await Promise.all([
        window.aivicApi.list(1), // 作業記録
        window.aivicApi.list(2)  // 中断記録
      ]);

      if (workRecords && interruptRecords) {
        renderSuspendedWorks(workRecords, interruptRecords);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 初期データ表示
  renderSuspendedWorks(tables[1]?.records || [], tables[2]?.records || []);

  // イベントリスナー設定

  // 作業選択
  container.addEventListener('click', async (e) => {
    const selectBtn = e.target.closest('.select-work-btn');
    if (selectBtn) {
      const workId = selectBtn.dataset.workId;
      const interruptId = selectBtn.dataset.interruptId;

      const workRecords = await window.aivicApi.list(1);
      const interruptRecords = await window.aivicApi.list(2);

      if (workRecords && interruptRecords) {
        const workRecord = workRecords.find(w => w.作業記録ID === workId);
        const interruptRecord = interruptRecords.find(i => i.中断記録ID === interruptId);

        if (workRecord && interruptRecord) {
          showWorkDetails(workRecord, interruptRecord);
        }
      }
    }
  });

  // 再開理由選択時の自動入力
  container.querySelector('#resume-reason-select').addEventListener('change', (e) => {
    const textarea = container.querySelector('#resume-reason-detail');
    if (e.target.value && !textarea.value.trim()) {
      textarea.value = e.target.value;
      updateCharCount();
    }
  });

  // 文字数カウンター
  container.querySelector('#resume-reason-detail').addEventListener('input', updateCharCount);

  // 作業再開ボタン
  container.querySelector('#btn-resume').addEventListener('click', () => {
    if (validateForm()) {
      container.querySelector('#confirm-dialog').classList.remove('hidden');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#resume-form').classList.add('hidden');
    selectedWorkRecord = null;
    selectedInterruptRecord = null;
  });

  // 確認ダイアログ - OK
  container.querySelector('#btn-confirm-ok').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').classList.add('hidden');
    resumeWork();
  });

  // 確認ダイアログ - キャンセル
  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').classList.add('hidden');
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    history.back();
  });

  // 初期時刻設定
  setCurrentTime();

  // データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let currentErrors = [];
  let currentWarnings = [];
  let isDuplicateCheck = false;

  // 作業項目マスタの初期化
  const workItemSelect = container.querySelector('#work-item');
  const workItemMaster = tables[3]?.records || [];
  workItemMaster.forEach(item => {
    if (item.有効フラグ) {
      const option = document.createElement('option');
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    }
  });

  // 入力フィールドの取得
  const workDate = container.querySelector('#work-date');
  const startTime = container.querySelector('#start-time');
  const endTime = container.querySelector('#end-time');
  const workContent = container.querySelector('#work-content');
  const workLocation = container.querySelector('#work-location');
  const workerName = container.querySelector('#worker-name');

  // ステータス表示要素
  const statusIcon = container.querySelector('#status-icon');
  const statusText = container.querySelector('#status-text');
  const saveIcon = container.querySelector('#save-icon');
  const saveText = container.querySelector('#save-text');
  const saveBtn = container.querySelector('#save-btn');

  // エラー・警告・提案表示要素
  const errorArea = container.querySelector('#error-area');
  const errorList = container.querySelector('#error-list');
  const warningArea = container.querySelector('#warning-area');
  const warningMessage = container.querySelector('#warning-message');
  const suggestionArea = container.querySelector('#suggestion-area');
  const suggestionMessage = container.querySelector('#suggestion-message');

  // ガイダンスパネル
  const guidancePanel = container.querySelector('#guidance-panel');
  const guidanceContent = container.querySelector('#guidance-content');

  // エラー詳細モーダル
  const errorDetailModal = container.querySelector('#error-detail-modal');
  const errorDetailContent = container.querySelector('#error-detail-content');

  // ガイダンス内容の定義
  const guidanceData = {
    'work-date': '作業を実施した日付を選択してください。未来の日付は選択できません。',
    'work-item': '実施した作業の種類を選択してください。該当する項目がない場合は管理者にお問い合わせください。',
    'start-time': '作業開始時刻を24時間形式で入力してください。例：09:00',
    'end-time': '作業終了時刻を24時間形式で入力してください。開始時刻より後の時刻を入力してください。',
    'work-content': '実施した作業の具体的な内容を200文字以内で入力してください。',
    'work-location': '作業を実施した場所を入力してください。例：A棟1階、現場事務所',
    'worker-name': '作業を実施した担当者の氏名を入力してください。'
  };

  // ステータス更新関数
  function updateStatus(isValid) {
    if (isValid) {
      statusIcon.style.background = '#10b981';
      statusIcon.innerHTML = '<span style="color: #fff; font-size: 12px;">✓</span>';
      statusText.textContent = '入力チェック通過';
      statusText.style.color = '#10b981';

      saveIcon.style.background = '#10b981';
      saveText.textContent = 'データ保存: 可能';
      saveText.style.color = '#10b981';
      saveBtn.disabled = false;
      saveBtn.style.opacity = '1';
    } else {
      statusIcon.style.background = '#ef4444';
      statusIcon.innerHTML = '<span style="color: #fff; font-size: 12px;">✗</span>';
      statusText.textContent = '入力エラーあり';
      statusText.style.color = '#ef4444';

      saveIcon.style.background = '#ef4444';
      saveText.textContent = 'データ保存: 不可';
      saveText.style.color = '#ef4444';
      saveBtn.disabled = true;
      saveBtn.style.opacity = '0.5';
    }
  }

  // バリデーション関数
  function validateInput() {
    currentErrors = [];
    currentWarnings = [];

    const workDateValue = workDate.value;
    const startTimeValue = startTime.value;
    const endTimeValue = endTime.value;
    const workContentValue = workContent.value.trim();
    const workLocationValue = workLocation.value.trim();
    const workerNameValue = workerName.value.trim();
    const workItemValue = workItemSelect.value;

    // 必須項目チェック
    if (!workDateValue) currentErrors.push('作業日は必須です');
    if (!workItemValue) currentErrors.push('作業項目は必須です');
    if (!startTimeValue) currentErrors.push('開始時刻は必須です');
    if (!endTimeValue) currentErrors.push('終了時刻は必須です');
    if (!workContentValue) currentErrors.push('作業内容は必須です');
    if (!workLocationValue) currentErrors.push('作業場所は必須です');
    if (!workerNameValue) currentErrors.push('担当者名は必須です');

    // 日付形式チェック
    if (workDateValue) {
      const workDateObj = new Date(workDateValue);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (workDateObj > today) {
        currentErrors.push('作業日に未来の日付は設定できません');
      }
    }

    // 時刻整合性チェック
    if (startTimeValue && endTimeValue) {
      const startMinutes = timeToMinutes(startTimeValue);
      const endMinutes = timeToMinutes(endTimeValue);

      if (startMinutes >= endMinutes) {
        currentErrors.push('開始時刻は終了時刻より前に設定してください');
      } else {
        const workMinutes = endMinutes - startMinutes;

        // 異常に短い作業時間（5分未満）
        if (workMinutes < 5) {
          currentWarnings.push('作業時間が異常に短く設定されています（' + workMinutes + '分）。入力内容を確認してください。');
        }

        // 異常に長い作業時間（12時間超）
        if (workMinutes > 720) {
          currentWarnings.push('作業時間が異常に長く設定されています（' + Math.floor(workMinutes/60) + '時間' + (workMinutes%60) + '分）。確認してください。');
        }

        // 24時間超過
        if (workMinutes > 1440) {
          currentErrors.push('作業時間が24時間を超過しています');
        }
      }
    }

    // 文字数チェック
    if (workContentValue.length > 200) {
      currentErrors.push('作業内容は200文字以内で入力してください（現在：' + workContentValue.length + '文字）');
    }

    // 重複データチェック（非同期）
    if (workDateValue && startTimeValue && !isDuplicateCheck) {
      checkDuplicateData(workDateValue, startTimeValue);
    }

    // 表示更新
    updateErrorDisplay();
    updateWarningDisplay();
    updateSuggestionDisplay();
    updateStatus(currentErrors.length === 0);
  }

  // 時刻を分に変換
  function timeToMinutes(timeStr) {
    const [hours, minutes] = timeStr.split(':').map(Number);
    return hours * 60 + minutes;
  }

  // 重複データチェック
  async function checkDuplicateData(date, time) {
    isDuplicateCheck = true;
    try {
      const records = await window.aivicApi.list(1); // 作業記録テーブル
      if (records) {
        const duplicate = records.find(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          const recordTime = new Date(record.作業開始時刻).toTimeString().slice(0, 5);
          return recordDate === date && recordTime === time;
        });

        if (duplicate) {
          currentErrors.push('指定された日時には既に作業記録が登録されています。別の日時を指定してください。');
          updateErrorDisplay();
          updateStatus(false);
        }
      }
    } catch (error) {
      console.error('重複チェックエラー:', error);
    }
    isDuplicateCheck = false;
  }

  // エラー表示更新
  function updateErrorDisplay() {
    if (currentErrors.length > 0) {
      errorList.innerHTML = currentErrors.map(error => `<li>${error}</li>`).join('');
      errorArea.style.display = 'block';
    } else {
      errorArea.style.display = 'none';
    }
  }

  // 警告表示更新
  function updateWarningDisplay() {
    if (currentWarnings.length > 0) {
      warningMessage.textContent = currentWarnings.join(' ');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 修正提案表示更新
  function updateSuggestionDisplay() {
    const suggestions = [];

    if (currentErrors.some(e => e.includes('開始時刻は終了時刻より前'))) {
      suggestions.push('開始時刻と終了時刻を確認し、正しい時刻を入力してください。');
    }

    if (currentErrors.some(e => e.includes('文字数'))) {
      suggestions.push('作業内容をより簡潔にまとめて200文字以内にしてください。');
    }

    if (currentWarnings.some(w => w.includes('異常に短い'))) {
      suggestions.push('作業時間が短すぎる可能性があります。休憩時間を除いた実作業時間を入力してください。');
    }

    if (suggestions.length > 0) {
      suggestionMessage.textContent = suggestions.join(' ');
      suggestionArea.style.display = 'block';
    } else {
      suggestionArea.style.display = 'none';
    }
  }

  // 入力フィールドのイベントリスナー
  const inputFields = [workDate, workItemSelect, startTime, endTime, workContent, workLocation, workerName];

  inputFields.forEach(field => {
    field.addEventListener('input', validateInput);
    field.addEventListener('blur', validateInput);

    // ガイダンス表示
    field.addEventListener('focus', (e) => {
      const fieldId = e.target.id;
      if (guidanceData[fieldId]) {
        guidanceContent.textContent = guidanceData[fieldId];
        guidancePanel.style.display = 'block';
      }
    });

    field.addEventListener('blur', () => {
      setTimeout(() => {
        if (!container.querySelector(':focus')) {
          guidancePanel.style.display = 'none';
        }
      }, 100);
    });
  });

  // エラー詳細ボタン
  container.querySelector('#error-detail-btn').addEventListener('click', () => {
    let detailHtml = '<h4 style="margin: 0 0 8px 0; font-size: 13px;">入力エラー詳細</h4>';

    if (currentErrors.length > 0) {
      detailHtml += '<div style="margin-bottom: 12px;"><strong>エラー項目:</strong><ul style="margin: 4px 0; padding-left: 16px;">';
      currentErrors.forEach(error => {
        detailHtml += `<li style="margin-bottom: 4px; color: #ef4444;">${error}</li>`;
      });
      detailHtml += '</ul></div>';
    }

    if (currentWarnings.length > 0) {
      detailHtml += '<div><strong>警告項目:</strong><ul style="margin: 4px 0; padding-left: 16px;">';
      currentWarnings.forEach(warning => {
        detailHtml += `<li style="margin-bottom: 4px; color: #f59e0b;">${warning}</li>`;
      });
      detailHtml += '</ul></div>';
    }

    errorDetailContent.innerHTML = detailHtml;
    errorDetailModal.style.display = 'flex';
  });

  // モーダル閉じる
  container.querySelector('#close-modal-btn').addEventListener('click', () => {
    errorDetailModal.style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  errorDetailModal.addEventListener('click', (e) => {
    if (e.target === errorDetailModal) {
      errorDetailModal.style.display = 'none';
    }
  });

  // 登録ボタン
  saveBtn.addEventListener('click', async () => {
    if (currentErrors.length > 0) return;

    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      作業日: workDate.value,
      作業開始時刻: `${workDate.value}T${startTime.value}:00`,
      作業終了時刻: `${workDate.value}T${endTime.value}:00`,
      作業時間: timeToMinutes(endTime.value) - timeToMinutes(startTime.value),
      プロジェクト名: workItemSelect.options[workItemSelect.selectedIndex]?.text || '',
      作業場所: workLocation.value,
      作業種別: workItemSelect.options[workItemSelect.selectedIndex]?.text || '',
      作業内容: workContent.value,
      進捗状況: '完了',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, workRecord);
      if (saved) {
        alert('工数記録を登録しました');
        clearForm();
        window.showScreen('scr-1778907133295'); // 工数記録画面へ
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  });

  // クリアボタン
  container.querySelector('#clear-btn').addEventListener('click', clearForm);

  function clearForm() {
    inputFields.forEach(field => {
      if (field.tagName === 'SELECT') {
        field.selectedIndex = 0;
      } else {
        field.value = '';
      }
    });
    currentErrors = [];
    currentWarnings = [];
    updateErrorDisplay();
    updateWarningDisplay();
    updateSuggestionDisplay();
    updateStatus(false);
    statusIcon.style.background = '#666';
    statusIcon.innerHTML = '<span style="color: #fff; font-size: 12px; font-weight: 600;">?</span>';
    statusText.textContent = '入力チェック待機中';
    statusText.style.color = 'var(--text)';
  }

  // エラーログ出力ボタン
  container.querySelector('#error-log-btn').addEventListener('click', async () => {
    try {
      const errorLogs = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (errorLogs) {
        let csvContent = '\uFEFF'; // BOM
        csvContent += '検出日時,異常値種別,検出項目,検出値,重要度,確認状況\n';

        errorLogs.forEach(log => {
          csvContent += `"${log.検出日時}","${log.異常値種別}","${log.検出項目}","${log.検出値}","${log.重要度}","${log.確認状況}"\n`;
        });

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `error_log_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();

        alert('エラーログを出力しました');
      }
    } catch (error) {
      console.error('エラーログ出力エラー:', error);
      alert('エラーログの出力に失敗しました');
    }
  });

  // 初期状態設定
  updateStatus(false);
}

function(container, apiUrl, tables) {
  // エラー情報の管理
  let errorData = {
    message: "データの保存に失敗しました。ネットワーク接続を確認してください。",
    code: "E001",
    time: new Date().toLocaleString('ja-JP', { 
      year: 'numeric', 
      month: '2-digit', 
      day: '2-digit', 
      hour: '2-digit', 
      minute: '2-digit', 
      second: '2-digit' 
    }),
    details: "TypeError: Cannot read property 'save' of undefined\nat saveWorkRecord (workRecord.js:45:12)\nat HTMLButtonElement.onclick (main.js:123:8)",
    isNetworkError: false,
    retryCount: 0
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorParam = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorData = { ...errorData, ...errorParam };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-message').textContent = errorData.message;
    container.querySelector('#error-code').textContent = errorData.code;
    container.querySelector('#error-time').textContent = errorData.time;
    container.querySelector('#error-stack').innerHTML = errorData.details.replace(/\n/g, '<br>');

    // ネットワークエラーの場合は追加情報を表示
    const networkErrorInfo = container.querySelector('#network-error-info');
    if (errorData.isNetworkError) {
      networkErrorInfo.classList.remove('hidden');
    } else {
      networkErrorInfo.classList.add('hidden');
    }
  }

  // 初期表示
  updateErrorDisplay();

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', async function() {
    const btn = this;
    const originalText = btn.textContent;

    // ボタンを無効化
    btn.disabled = true;
    btn.textContent = '再試行中...';
    btn.style.background = 'var(--text-muted)';

    try {
      // 再試行回数を増加
      errorData.retryCount++;

      // ネットワーク接続テスト
      const response = await fetch(apiUrl + '/api/health', { 
        method: 'GET',
        timeout: 5000 
      });

      if (response.ok) {
        // 成功時は元の画面に戻る
        if (window.history.length > 1) {
          window.history.back();
        } else {
          window.showScreen('scr-1778907133295'); // 工数記録画面
        }
      } else {
        throw new Error('サーバーエラー');
      }
    } catch (error) {
      // 再試行失敗
      errorData.message = `再試行に失敗しました（${errorData.retryCount}回目）。${error.message.includes('fetch') ? 'ネットワーク接続を確認してください。' : 'しばらく時間をおいて再度お試しください。'}`;
      errorData.isNetworkError = error.message.includes('fetch') || error.message.includes('network');
      errorData.time = new Date().toLocaleString('ja-JP', { 
        year: 'numeric', 
        month: '2-digit', 
        day: '2-digit', 
        hour: '2-digit', 
        minute: '2-digit', 
        second: '2-digit' 
      });

      updateErrorDisplay();
    } finally {
      // ボタンを復元
      btn.disabled = false;
      btn.textContent = originalText;
      btn.style.background = 'var(--primary)';
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', function() {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', function() {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム画面として）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', async function() {
    try {
      // 管理者連絡機能の利用可能性をチェック
      const response = await fetch(apiUrl + '/api/contact/check', { 
        method: 'GET',
        timeout: 3000 
      });

      if (response.ok) {
        // 連絡画面に遷移（緊急報告画面を使用）
        window.showScreen('scr-1778907330826');
      } else {
        throw new Error('連絡機能が利用できません');
      }
    } catch (error) {
      // 管理者連絡機能エラー時は代替連絡先を表示
      const contactErrorInfo = container.querySelector('#contact-error-info');
      contactErrorInfo.classList.remove('hidden');

      // 5秒後に自動で非表示
      setTimeout(() => {
        contactErrorInfo.classList.add('hidden');
      }, 5000);
    }
  });

  // エラー詳細表示切り替えボタン
  container.querySelector('#btn-toggle-details').addEventListener('click', function() {
    const detailsDiv = container.querySelector('#error-details');
    const btn = this;

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      btn.textContent = 'エラー詳細を非表示';
    } else {
      detailsDiv.classList.add('hidden');
      btn.textContent = 'エラー詳細を表示';
    }
  });

  // セッション切れの検出
  function checkSessionStatus() {
    const token = localStorage.getItem('authToken') || sessionStorage.getItem('authToken');
    if (!token) {
      // セッション切れの場合はログイン画面への遷移ボタンを追加
      const actionsDiv = container.querySelector('.error-actions');
      if (!container.querySelector('#btn-login')) {
        const loginBtn = document.createElement('button');
        loginBtn.id = 'btn-login';
        loginBtn.className = 'action-btn';
        loginBtn.style.cssText = 'background: var(--primary); color: #fff; border: none; padding: 8px 14px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; grid-column: 1 / -1; margin-top: 8px;';
        loginBtn.textContent = 'ログイン画面へ';
        loginBtn.addEventListener('click', function() {
          window.location.href = './login.html';
        });
        actionsDiv.appendChild(loginBtn);
      }
    }
  }

  // 初期セッション状態チェック
  checkSessionStatus();

  // 長いエラーメッセージの制限処理
  function limitErrorMessage() {
    const messageDiv = container.querySelector('#error-message');
    const maxLength = 500;

    if (errorData.message.length > maxLength) {
      const truncated = errorData.message.substring(0, maxLength) + '...';
      messageDiv.innerHTML = `
        <div>${truncated}</div>
        <button style="background: none; border: none; color: var(--primary); font-size: 12px; cursor: pointer; text-decoration: underline; margin-top: 4px;" onclick="this.previousElementSibling.textContent = '${errorData.message.replace(/'/g, "\\'")}'; this.style.display = 'none';">
          全文を表示
        </button>
      `;
    }
  }

  limitErrorMessage();

  // 連続クリック防止のためのデバウンス処理
  let isProcessing = false;

  container.addEventListener('click', function(e) {
    if (e.target.matches('button') && !e.target.disabled) {
      if (isProcessing) {
        e.preventDefault();
        return false;
      }

      isProcessing = true;
      setTimeout(() => {
        isProcessing = false;
      }, 1000);
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', function() {
    const networkErrorInfo = container.querySelector('#network-error-info');
    if (!networkErrorInfo.classList.contains('hidden')) {
      networkErrorInfo.style.background = 'rgba(34, 197, 94, 0.1)';
      networkErrorInfo.style.borderColor = 'rgba(34, 197, 94, 0.3)';
      networkErrorInfo.querySelector('div').innerHTML = '<strong>ネットワーク接続が復旧しました。</strong> 再試行ボタンをクリックしてください。';
    }
  });

  window.addEventListener('offline', function() {
    errorData.isNetworkError = true;
    errorData.message = 'ネットワーク接続が切断されました。接続を確認してください。';
    updateErrorDisplay();
  });
}

function(container, apiUrl, tables) {
  let interruptRecords = [];

  // 作業項目マスタの初期化
  function initWorkItems() {
    const workItemSelect = container.querySelector("#work-item");
    const workItems = tables[3]?.records || [];
    workItems.forEach(item => {
      const option = document.createElement("option");
      option.value = item.作業項目ID;
      option.textContent = item.作業項目名;
      workItemSelect.appendChild(option);
    });
  }

  // 実働時間計算
  function calculateWorkTime() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;

    if (!startTime || !endTime) {
      container.querySelector("#actual-work-time").value = "";
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間をまたぐ場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60)) - breakTime;

    if (diffMinutes < 0) {
      container.querySelector("#actual-work-time").value = "エラー: 休憩時間が実働時間を超過";
      return;
    }

    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    container.querySelector("#actual-work-time").value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 中断記録の再描画
  function renderInterrupts() {
    const tbody = container.querySelector("#interrupt-tbody");
    tbody.innerHTML = interruptRecords.map((record, index) => {
      const startTime = record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : record.startTime;
      const endTime = record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : record.endTime;
      const duration = record.中断時間 ? `${record.中断時間}分` : calculateInterruptDuration(record.startTime, record.endTime);

      return `
        <tr data-index="${index}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.中断理由区分 || record.reason}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${duration}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary delete-interrupt-btn" data-index="${index}" style="font-size: 11px; padding: 4px 8px;">削除</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 中断時間計算
  function calculateInterruptDuration(startTime, endTime) {
    if (!startTime || !endTime) return "";

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    return `${diffMinutes}分`;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
    setTimeout(() => {
      errorDiv.style.display = "none";
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector("#work-date").value;
    const workItem = container.querySelector("#work-item").value;
    const workLocation = container.querySelector("#work-location").value;
    const startTime = container.querySelector("#start-time").value;
    const workDetails = container.querySelector("#work-details").value;

    if (!workDate) {
      showError("作業日付を入力してください");
      return false;
    }

    // 未来日付チェック
    const today = new Date();
    const selectedDate = new Date(workDate);
    if (selectedDate > today) {
      showError("未来の日付は選択できません");
      return false;
    }

    if (!workItem) {
      showError("作業項目を選択してください");
      return false;
    }

    if (!workLocation.trim()) {
      showError("作業場所を入力してください");
      return false;
    }

    if (!startTime) {
      showError("開始時刻を入力してください");
      return false;
    }

    if (!workDetails.trim()) {
      showError("作業内容詳細を入力してください");
      return false;
    }

    const endTime = container.querySelector("#end-time").value;
    if (endTime) {
      // 時刻フォーマットチェック
      const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
      if (!timeRegex.test(startTime)) {
        showError("開始時刻の形式が正しくありません");
        return false;
      }
      if (!timeRegex.test(endTime)) {
        showError("終了時刻の形式が正しくありません");
        return false;
      }

      // 同じ時刻チェック
      if (startTime === endTime) {
        showError("開始時刻と終了時刻が同じです");
        return false;
      }

      // 実働時間チェック
      const actualWorkTime = container.querySelector("#actual-work-time").value;
      if (actualWorkTime.includes("エラー")) {
        showError("休憩時間が実働時間を超過しています");
        return false;
      }
    }

    return true;
  }

  // 初期化
  initWorkItems();

  // 現在の日付を設定
  const today = new Date();
  container.querySelector("#work-date").value = today.toISOString().split('T')[0];

  // 実働時間計算のイベントリスナー
  container.querySelector("#start-time").addEventListener("change", calculateWorkTime);
  container.querySelector("#end-time").addEventListener("change", calculateWorkTime);
  container.querySelector("#break-time").addEventListener("input", calculateWorkTime);

  // 中断記録追加
  container.querySelector("#btn-add-interrupt").addEventListener("click", () => {
    const reason = container.querySelector("#interrupt-reason").value;
    const startTime = container.querySelector("#interrupt-start-time").value;
    const endTime = container.querySelector("#interrupt-end-time").value;

    if (!reason) {
      showError("中断理由を選択してください");
      return;
    }

    if (!startTime) {
      showError("中断開始時刻を入力してください");
      return;
    }

    const record = {
      reason: reason,
      startTime: startTime,
      endTime: endTime || ""
    };

    interruptRecords.push(record);
    renderInterrupts();

    // フォームクリア
    container.querySelector("#interrupt-reason").value = "";
    container.querySelector("#interrupt-start-time").value = "";
    container.querySelector("#interrupt-end-time").value = "";
  });

  // 中断記録削除
  container.addEventListener("click", (e) => {
    const deleteBtn = e.target.closest(".delete-interrupt-btn");
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      interruptRecords.splice(index, 1);
      renderInterrupts();
    }
  });

  // 登録ボタン
  container.querySelector("#btn-save").addEventListener("click", async () => {
    if (!validateForm()) return;

    const workDate = container.querySelector("#work-date").value;
    const workItem = container.querySelector("#work-item").value;
    const workLocation = container.querySelector("#work-location").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;
    const workDetails = container.querySelector("#work-details").value;
    const notes = container.querySelector("#notes").value;

    // 作業開始時刻と終了時刻をタイムスタンプに変換
    const startDateTime = new Date(`${workDate} ${startTime}`);
    const endDateTime = endTime ? new Date(`${workDate} ${endTime}`) : null;

    // 24時間をまたぐ場合の調整
    if (endDateTime && endDateTime <= startDateTime) {
      endDateTime.setDate(endDateTime.getDate() + 1);
    }

    // 実働時間計算（分単位）
    let workTimeMinutes = null;
    if (endDateTime) {
      const diffMs = endDateTime - startDateTime;
      workTimeMinutes = Math.floor(diffMs / (1000 * 60)) - breakTime;
    }

    const workRecord = {
      作業員ID: "current-user-id", // 実際の実装では現在のユーザーIDを使用
      作業日: startDateTime.toISOString(),
      作業開始時刻: startDateTime.toISOString(),
      作業終了時刻: endDateTime ? endDateTime.toISOString() : null,
      作業時間: workTimeMinutes,
      プロジェクト名: "現場作業", // 実際の実装ではプロジェクト選択機能を追加
      作業場所: workLocation,
      作業種別: workItem,
      作業内容: workDetails,
      進捗状況: endDateTime ? "完了" : "作業中",
      備考: notes,
      承認状態: "未承認",
      作成者ID: "current-user-id"
    };

    try {
      const saved = await window.aivicApi.save(1, workRecord);
      if (saved) {
        // 中断記録も保存
        for (const interrupt of interruptRecords) {
          const interruptStartDateTime = new Date(`${workDate} ${interrupt.startTime}`);
          const interruptEndDateTime = interrupt.endTime ? new Date(`${workDate} ${interrupt.endTime}`) : null;

          if (interruptEndDateTime && interruptEndDateTime <= interruptStartDateTime) {
            interruptEndDateTime.setDate(interruptEndDateTime.getDate() + 1);
          }

          const interruptRecord = {
            作業記録ID: saved.作業記録ID,
            中断開始日時: interruptStartDateTime.toISOString(),
            中断終了日時: interruptEndDateTime ? interruptEndDateTime.toISOString() : null,
            中断理由区分: interrupt.reason,
            中断理由詳細: "",
            中断時間: interruptEndDateTime ? Math.floor((interruptEndDateTime - interruptStartDateTime) / (1000 * 60)) : null,
            影響度: "軽微",
            対応状況: "対応済み",
            記録者ID: "current-user-id"
          };

          await window.aivicApi.save(2, interruptRecord);
        }

        alert("工数記録が正常に登録されました");

        // フォームクリア
        container.querySelector("#work-form").reset();
        container.querySelector("#actual-work-time").value = "";
        interruptRecords = [];
        renderInterrupts();

        // 現在の日付を再設定
        container.querySelector("#work-date").value = today.toISOString().split('T')[0];
      }
    } catch (error) {
      showError("登録に失敗しました");
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    if (confirm("入力内容をクリアしますか？")) {
      container.querySelector("#work-form").reset();
      container.querySelector("#actual-work-time").value = "";
      interruptRecords = [];
      renderInterrupts();
      container.querySelector("#work-date").value = today.toISOString().split('T')[0];
    }
  });

  // 作業中断ボタン
  container.querySelector("#btn-interrupt").addEventListener("click", () => {
    window.showScreen("scr-1778907238439");
  });

  // 作業終了ボタン
  container.querySelector("#btn-end-work").addEventListener("click", () => {
    window.showScreen("scr-1778907199709");
  });

  // 初期描画
  renderInterrupts();
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateTargetRecords();
      populateWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のプルダウンを設定
  function populateTargetRecords() {
    const select = container.querySelector('#target-record');
    select.innerHTML = '<option value="">記録を選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID || record.id;
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString() : '';
      const projectName = record.プロジェクト名 || '';
      const workType = record.作業種別 || '';
      option.textContent = `${workDate} - ${projectName} (${workType})`;
      select.appendChild(option);
    });
  }

  // 作業項目のプルダウンを設定
  function populateWorkItems() {
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.filter(item => item.有効フラグ).forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID || item.id;
      option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
      select.appendChild(option);
    });
  }

  // 修正対象記録選択時の処理
  container.querySelector('#target-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      container.querySelector('#correction-form').style.display = 'none';
      container.querySelector('#original-data').style.display = 'none';
      selectedRecord = null;
      return;
    }

    selectedRecord = workRecords.find(r => (r.作業記録ID || r.id) === recordId);
    if (selectedRecord) {
      populateForm(selectedRecord);
      showOriginalData(selectedRecord);
      container.querySelector('#correction-form').style.display = 'block';
      container.querySelector('#original-data').style.display = 'block';
    }
  });

  // フォームに既存データを設定
  function populateForm(record) {
    const workDate = record.作業日 ? new Date(record.作業日).toISOString().split('T')[0] : '';
    container.querySelector('#work-date').value = workDate;

    if (record.作業開始時刻) {
      const startTime = new Date(record.作業開始時刻);
      container.querySelector('#start-time').value = `${startTime.getHours().toString().padStart(2, '0')}:${startTime.getMinutes().toString().padStart(2, '0')}`;
    }

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      container.querySelector('#end-time').value = `${endTime.getHours().toString().padStart(2, '0')}:${endTime.getMinutes().toString().padStart(2, '0')}`;
    }

    // 作業項目を設定（プロジェクト名や作業種別から推測）
    const workItemSelect = container.querySelector('#work-item');
    const matchingItem = workItems.find(item => 
      item.作業項目名 === record.作業種別 || item.作業項目コード === record.作業種別
    );
    if (matchingItem) {
      workItemSelect.value = matchingItem.作業項目ID || matchingItem.id;
    }

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => br.作業記録ID === (record.作業記録ID || record.id));
    if (breakRecord) {
      if (breakRecord.中断開始日時) {
        const breakTime = new Date(breakRecord.中断開始日時);
        container.querySelector('#break-time').value = `${breakTime.getHours().toString().padStart(2, '0')}:${breakTime.getMinutes().toString().padStart(2, '0')}`;
      }
      container.querySelector('#break-reason').value = breakRecord.中断理由区分 || '';
    }

    calculateTimes();
  }

  // 修正前データを表示
  function showOriginalData(record) {
    const originalContent = container.querySelector('#original-content');
    const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString() : '-';
    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString() : '-';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString() : '-';
    const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

    originalContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
        <div>作業日: ${workDate}</div>
        <div>プロジェクト: ${record.プロジェクト名 || '-'}</div>
        <div>開始時刻: ${startTime}</div>
        <div>終了時刻: ${endTime}</div>
        <div>作業時間: ${workTime}</div>
        <div>作業種別: ${record.作業種別 || '-'}</div>
      </div>
    `;
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        let breakMinutes = 0;

        if (breakTime) {
          const breakDateTime = new Date(`2000-01-01T${breakTime}`);
          if (breakDateTime >= start && breakDateTime <= end) {
            // 簡易的に30分の中断とする
            breakMinutes = 30;
          }
        }

        const actualMinutes = totalMinutes - breakMinutes;

        container.querySelector('#break-duration').textContent = breakMinutes > 0 ? `${breakMinutes}分` : '-';
        container.querySelector('#actual-work-time').textContent = `${Math.floor(actualMinutes / 60)}時間${actualMinutes % 60}分`;

        // 異常値チェック
        checkAnomalies(totalMinutes, actualMinutes, breakMinutes);
      }
    }
  }

  // 異常値チェック
  function checkAnomalies(totalMinutes, actualMinutes, breakMinutes) {
    const warnings = [];

    if (actualMinutes > 12 * 60) { // 12時間超
      warnings.push('実作業時間が12時間を超えています');
    }

    if (totalMinutes > 24 * 60) { // 24時間超
      warnings.push('総作業時間が24時間を超えています');
    }

    if (breakMinutes > totalMinutes * 0.5) { // 中断時間が総時間の50%超
      warnings.push('中断時間が総作業時間の50%を超えています');
    }

    const warningArea = container.querySelector('#warning-area');
    if (warnings.length > 0) {
      container.querySelector('#warning-message').textContent = warnings.join('、');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!container.querySelector('#target-record').value) {
      errors.push('修正対象記録を選択してください');
    }

    if (!container.querySelector('#correction-reason').value.trim()) {
      errors.push('修正理由を入力してください');
    }

    const workDate = container.querySelector('#work-date').value;
    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      if (date > today) {
        errors.push('作業日付に未来の日付は入力できません');
      }
      if (date < new Date('1900-01-01')) {
        errors.push('作業日付が無効です');
      }
    }

    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      if (start >= end) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }
    }

    const breakTime = container.querySelector('#break-time').value;
    if (breakTime && startTime && endTime) {
      const breakDateTime = new Date(`2000-01-01T${breakTime}`);
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      if (breakDateTime < start || breakDateTime > end) {
        errors.push('中断時刻が作業時間外です');
      }
    }

    const errorArea = container.querySelector('#error-area');
    if (errors.length > 0) {
      container.querySelector('#error-message').textContent = errors.join('、');
      errorArea.style.display = 'block';
      return false;
    } else {
      errorArea.style.display = 'none';
      return true;
    }
  }

  // 時間入力時の計算
  ['#start-time', '#end-time', '#break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  // 修正理由の文字数カウント
  container.querySelector('#correction-reason').addEventListener('input', function() {
    const count = this.value.length;
    container.querySelector('#reason-count').textContent = count;

    if (count > 200) {
      this.value = this.value.substring(0, 200);
      container.querySelector('#reason-count').textContent = '200';
    }
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    try {
      const recordId = container.querySelector('#target-record').value;
      const workDate = container.querySelector('#work-date').value;
      const startTime = container.querySelector('#start-time').value;
      const endTime = container.querySelector('#end-time').value;
      const workItemId = container.querySelector('#work-item').value;
      const breakTime = container.querySelector('#break-time').value;
      const breakReason = container.querySelector('#break-reason').value;
      const correctionReason = container.querySelector('#correction-reason').value;

      // 作業記録の更新
      const updateData = {
        ...selectedRecord
      };

      if (workDate) {
        updateData.作業日 = new Date(workDate).toISOString();
      }

      if (startTime) {
        const startDateTime = new Date(`${workDate}T${startTime}`);
        updateData.作業開始時刻 = startDateTime.toISOString();
      }

      if (endTime) {
        const endDateTime = new Date(`${workDate}T${endTime}`);
        updateData.作業終了時刻 = endDateTime.toISOString();
      }

      if (workItemId) {
        const workItem = workItems.find(item => (item.作業項目ID || item.id) === workItemId);
        if (workItem) {
          updateData.作業種別 = workItem.作業項目名;
        }
      }

      // 作業時間を再計算
      if (startTime && endTime) {
        const start = new Date(`${workDate}T${startTime}`);
        const end = new Date(`${workDate}T${endTime}`);
        const totalMinutes = (end - start) / (1000 * 60);
        updateData.作業時間 = Math.floor(totalMinutes);
      }

      updateData.更新日時 = new Date().toISOString();

      const updated = await window.aivicApi.update(1, recordId, updateData);
      if (updated) {
        // 中断記録の更新/作成
        if (breakTime && breakReason) {
          const existingBreak = breakRecords.find(br => br.作業記録ID === recordId);
          const breakData = {
            作業記録ID: recordId,
            中断開始日時: new Date(`${workDate}T${breakTime}`).toISOString(),
            中断理由区分: breakReason,
            中断時間: 30, // 簡易的に30分
            対応状況: '対応中',
            記録者ID: selectedRecord.作業員ID,
            更新日時: new Date().toISOString()
          };

          if (existingBreak) {
            await window.aivicApi.update(2, existingBreak.中断記録ID || existingBreak.id, breakData);
          } else {
            breakData.中断記録ID = crypto.randomUUID();
            breakData.作成日時 = new Date().toISOString();
            await window.aivicApi.save(2, breakData);
          }
        }

        alert('修正が完了しました');

        // フォームをリセット
        container.querySelector('#target-record').value = '';
        container.querySelector('#correction-reason').value = '';
        container.querySelector('#reason-count').textContent = '0';
        container.querySelector('#correction-form').style.display = 'none';
        container.querySelector('#original-data').style.display = 'none';
        container.querySelector('#warning-area').style.display = 'none';
        container.querySelector('#error-area').style.display = 'none';

        // データを再読み込み
        await loadData();
      }
    } catch (error) {
      console.error('保存エラー:', error);
      container.querySelector('#error-message').textContent = '保存に失敗しました';
      container.querySelector('#error-area').style.display = 'block';
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let uploadedPhotos = [];
  let currentUser = null;

  // 現在のユーザー情報を取得
  async function loadCurrentUser() {
    try {
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (users && users.length > 0) {
        currentUser = users[0]; // 最初のユーザーを現在のユーザーとする
        const reporterNameInput = container.querySelector('#reporter-name');
        if (reporterNameInput && currentUser) {
          reporterNameInput.value = currentUser.氏名 || '';
        }
      }
    } catch (error) {
      console.error('ユーザー情報の取得に失敗:', error);
    }
  }

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタテーブル
      const workItemSelect = container.querySelector('#work-item');
      if (workItems && workItems.length > 0) {
        workItems
          .filter(item => item.有効フラグ)
          .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
          .forEach(item => {
            const option = document.createElement('option');
            option.value = item.作業項目ID;
            option.textContent = item.作業項目名;
            workItemSelect.appendChild(option);
          });
      }
    } catch (error) {
      console.error('作業項目の取得に失敗:', error);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess() {
    const successDiv = container.querySelector('#success-message');
    const formCard = container.querySelector('.card');
    const headerButtons = container.querySelector('.emergency-report-container > div:first-child');

    formCard.style.display = 'none';
    headerButtons.style.display = 'none';
    successDiv.style.display = 'block';
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!selectedUrgency) {
      errors.push('緊急度を選択してください');
    }

    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      errors.push('報告種別を選択してください');
    }

    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    if (!occurrenceDateTime) {
      errors.push('発生日時を入力してください');
    } else {
      const selectedDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (selectedDate > now) {
        errors.push('発生日時に未来の日付は入力できません');
      }
    }

    const occurrenceLocation = container.querySelector('#occurrence-location').value.trim();
    if (!occurrenceLocation) {
      errors.push('発生場所を入力してください');
    }

    const emergencyContent = container.querySelector('#emergency-content').value.trim();
    if (!emergencyContent) {
      errors.push('緊急事態内容を入力してください');
    } else if (emergencyContent.length > 1000) {
      errors.push('緊急事態内容は1000文字以内で入力してください');
    }

    const contactPhone = container.querySelector('#contact-phone').value.trim();
    if (!contactPhone) {
      errors.push('連絡先電話番号を入力してください');
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(contactPhone)) {
        errors.push('正しい電話番号の形式で入力してください');
      }
    }

    return errors;
  }

  // フォームデータ収集
  function collectFormData() {
    return {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value.trim(),
      作業項目ID: container.querySelector('#work-item').value || null,
      緊急事態内容: container.querySelector('#emergency-content').value.trim(),
      添付写真: uploadedPhotos,
      報告者ID: currentUser ? currentUser.ユーザーID : null,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value.trim(),
      報告日時: new Date().toISOString(),
      対応状況: '未対応',
      確認状況: '未確認'
    };
  }

  // 緊急度ボタンのイベント
  container.querySelectorAll('.urgency-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // 全ボタンのスタイルをリセット
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = 'var(--text)';
        b.style.borderColor = 'rgba(255,255,255,0.18)';
      });

      // 選択されたボタンのスタイル
      btn.style.background = 'var(--primary)';
      btn.style.color = '#fff';
      btn.style.borderColor = 'var(--primary)';

      selectedUrgency = btn.dataset.value;
    });
  });

  // 文字数カウント
  const emergencyContentTextarea = container.querySelector('#emergency-content');
  const charCountSpan = container.querySelector('#char-count');

  emergencyContentTextarea.addEventListener('input', () => {
    const length = emergencyContentTextarea.value.length;
    charCountSpan.textContent = `(${length}/1000)`;

    if (length > 1000) {
      charCountSpan.style.color = '#dc2626';
    } else {
      charCountSpan.style.color = 'var(--text-muted)';
    }
  });

  // 写真アップロード処理
  const photoUploadArea = container.querySelector('#photo-upload-area');
  const photoInput = container.querySelector('#photo-input');
  const photoPreview = container.querySelector('#photo-preview');

  photoUploadArea.addEventListener('click', () => {
    photoInput.click();
  });

  photoUploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'var(--primary)';
    photoUploadArea.style.background = 'rgba(0,0,0,0.2)';
  });

  photoUploadArea.addEventListener('dragleave', () => {
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    photoUploadArea.style.background = 'rgba(0,0,0,0.1)';
  });

  photoUploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    photoUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    photoUploadArea.style.background = 'rgba(0,0,0,0.1)';

    const files = Array.from(e.dataTransfer.files);
    handlePhotoFiles(files);
  });

  photoInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    handlePhotoFiles(files);
  });

  function handlePhotoFiles(files) {
    const imageFiles = files.filter(file => file.type.startsWith('image/'));

    if (imageFiles.length === 0) {
      showError('サポートされていないファイル形式です。jpg、png形式のファイルをアップロードしてください。');
      return;
    }

    if (uploadedPhotos.length + imageFiles.length > 5) {
      showError('写真は最大5枚まで添付できます。');
      return;
    }

    imageFiles.forEach(file => {
      if (file.size > 5 * 1024 * 1024) { // 5MB
        showError(`ファイル「${file.name}」のサイズが上限を超えています。5MB以下のファイルを選択してください。`);
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        const photoData = {
          name: file.name,
          data: e.target.result,
          size: file.size
        };

        uploadedPhotos.push(photoData);
        renderPhotoPreview();
      };
      reader.readAsDataURL(file);
    });
  }

  function renderPhotoPreview() {
    photoPreview.innerHTML = uploadedPhotos.map((photo, index) => `
      <div style="position: relative; display: inline-block;">
        <img src="${photo.data}" alt="${photo.name}" style="width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);">
        <button type="button" class="remove-photo-btn" data-index="${index}" style="position: absolute; top: -6px; right: -6px; width: 20px; height: 20px; border-radius: 50%; background: #dc2626; color: #fff; border: none; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
      </div>
    `).join('');
  }

  // 写真削除
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-photo-btn')) {
      const index = parseInt(e.target.dataset.index);
      uploadedPhotos.splice(index, 1);
      renderPhotoPreview();
    }
  });

  // 下書き保存
  container.querySelector('#btn-draft-save').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.下書きフラグ = true;

    try {
      // 異常値検出ログテーブルに下書きとして保存
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: 'draft-' + Date.now(),
        ユーザーID: currentUser ? currentUser.ユーザーID : null,
        異常値種別: '下書き保存',
        検出項目: '緊急報告内容',
        検出値: JSON.stringify(formData),
        閾値: 'N/A',
        重要度: '低',
        確認状況: '下書き',
        通知送信フラグ: false,
        検出日時: new Date().toISOString()
      });

      if (saved) {
        const successDiv = container.querySelector('#success-message');
        successDiv.innerHTML = `
          <div style="font-weight: 600; margin-bottom: 8px;">下書きが保存されました</div>
          <div style="font-size: 12px; color: var(--text-muted);">後で編集を続けることができます。</div>
        `;
        successDiv.style.display = 'block';
        setTimeout(() => {
          successDiv.style.display = 'none';
        }, 3000);
      }
    } catch (error) {
      showError('下書きの保存に失敗しました。');
    }
  });

  // 緊急報告送信
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    const formData = collectFormData();

    try {
      // 異常値検出ログテーブルに緊急報告として保存
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: 'emergency-' + Date.now(),
        ユーザーID: currentUser ? currentUser.ユーザーID : null,
        異常値種別: '緊急報告',
        検出項目: '緊急事態',
        検出値: JSON.stringify(formData),
        閾値: selectedUrgency,
        重要度: selectedUrgency,
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: new Date().toISOString()
      });

      if (saved) {
        showSuccess();
      }
    } catch (error) {
      showError('緊急報告の送信に失敗しました。');
    }
  });

  // 報告完了ボタン
  container.addEventListener('click', (e) => {
    if (e.target.id === 'btn-complete') {
      window.showScreen("scr-1778907133295");
    }
  });

  // 初期化処理
  loadCurrentUser();
  loadWorkItems();

  // 現在日時を発生日時のデフォルト値に設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector('#occurrence-datetime').value = localDateTime;
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let selectedRecord = null;
  let originalData = null;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      renderWorkRecordOptions();
      renderWorkItemOptions();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 作業記録選択肢を描画
  function renderWorkRecordOptions() {
    const select = container.querySelector('#select-work-record');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.id;
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      option.textContent = `${workDate} - ${record.作業内容?.substring(0, 30) || ''}...`;
      select.appendChild(option);
    });
  }

  // 作業項目選択肢を描画
  function renderWorkItemOptions() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.forEach(item => {
      const option = document.createElement('option');
      option.value = item.id;
      option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
      select.appendChild(option);
    });
  }

  // 時刻計算
  function calculateWorkTime() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#input-total-time').value = '';
      container.querySelector('#input-net-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間跨ぎの場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = totalMinutes - breakTime;

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector('#input-total-time').value = `${totalHours}時間${totalMins}分`;
    container.querySelector('#input-net-time').value = netMinutes >= 0 ? `${netHours}時間${netMins}分` : '計算エラー';

    // 異常値チェック
    checkAbnormalValues(totalMinutes, breakTime);
  }

  // 異常値チェック
  function checkAbnormalValues(totalMinutes, breakTime) {
    const warningArea = container.querySelector('#warning-area');
    const warningMessage = container.querySelector('#warning-message');

    let warnings = [];

    if (totalMinutes > 12 * 60) { // 12時間超過
      warnings.push('作業時間が12時間を超えています。');
    }

    if (breakTime > totalMinutes) {
      warnings.push('中断時間が作業時間を超過しています。');
    }

    if (totalMinutes === 0) {
      warnings.push('作業時間が0分です。開始時刻と終了時刻を確認してください。');
    }

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join(' ');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // エラー表示
  function showError(message) {
    const errorArea = container.querySelector('#error-area');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorArea.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-area').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    hideError();

    const recordId = container.querySelector('#select-work-record').value;
    if (!recordId) {
      showError('修正対象の作業記録を選択してください。');
      return false;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください。');
      return false;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    if (end <= start && startTime === endTime) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }
    const totalMinutes = (end - start) / (1000 * 60);

    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています。');
      return false;
    }

    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    if (!correctionReason) {
      showError('修正理由を入力してください。');
      return false;
    }

    if (correctionReason.length > 500) {
      showError('修正理由は500文字以内で入力してください。');
      return false;
    }

    const workDetail = container.querySelector('#textarea-work-detail').value;
    if (workDetail.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      selectedRecord = null;
      originalData = null;
      container.querySelector('#input-work-date').value = '';
      container.querySelector('#input-start-time').value = '';
      container.querySelector('#input-end-time').value = '';
      container.querySelector('#input-break-time').value = '';
      container.querySelector('#select-work-item').value = '';
      container.querySelector('#textarea-work-detail').value = '';
      container.querySelector('#input-correction-reason').value = '';
      calculateWorkTime();
      return;
    }

    selectedRecord = workRecords.find(r => r.id === recordId);
    originalData = { ...selectedRecord };

    if (selectedRecord) {
      const workDate = new Date(selectedRecord.作業日).toLocaleDateString('ja-JP');
      container.querySelector('#input-work-date').value = workDate;

      const startTime = new Date(selectedRecord.作業開始時刻);
      const endTime = selectedRecord.作業終了時刻? new Date(selectedRecord.作業終了時刻) : null;

      container.querySelector('#input-start-time').value = startTime.toTimeString().substring(0, 5);
      if (endTime) {
        container.querySelector('#input-end-time').value = endTime.toTimeString().substring(0, 5);
      }

      container.querySelector('#textarea-work-detail').value = selectedRecord.作業内容 || '';

      // 中断時間を計算（中断記録から）
      window.aivicApi.list(2).then(breakRecords => {
        const totalBreakTime = breakRecords
          .filter(br => br.作業記録ID === recordId)
          .reduce((sum, br) => sum + (br.中断時間 || 0), 0);
        container.querySelector('#input-break-time').value = totalBreakTime;
        calculateWorkTime();
      });

      calculateWorkTime();
    }
  });

  // 時刻変更時の計算
  container.querySelector('#input-start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#input-end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#input-break-time').addEventListener('input', calculateWorkTime);

  // 元データ参照ボタン
  container.querySelector('#btn-original-data').addEventListener('click', function() {
    if (!originalData) {
      showError('修正対象の作業記録を選択してください。');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const startTime = new Date(originalData.作業開始時刻).toLocaleString('ja-JP');
    const endTime = originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toLocaleString('ja-JP') : '未設定';

    content.innerHTML = `
      <div style="margin-bottom: 12px;"><strong>作業日:</strong> ${new Date(originalData.作業日).toLocaleDateString('ja-JP')}</div>
      <div style="margin-bottom: 12px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 12px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 12px;"><strong>作業時間:</strong> ${originalData.作業時間 || 0}分</div>
      <div style="margin-bottom: 12px;"><strong>プロジェクト名:</strong> ${originalData.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>作業場所:</strong> ${originalData.作業場所 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>作業種別:</strong> ${originalData.作業種別 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>作業内容:</strong> ${originalData.作業内容 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>進捗状況:</strong> ${originalData.進捗状況 || ''}</div>
      <div style="margin-bottom: 12px;"><strong>備考:</strong> ${originalData.備考 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen("scr-1778907367889");
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    try {
      const recordId = container.querySelector('#select-work-record').value;
      const startTime = container.querySelector('#input-start-time').value;
      const endTime = container.querySelector('#input-end-time').value;
      const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
      const workDetail = container.querySelector('#textarea-work-detail').value;
      const correctionReason = container.querySelector('#input-correction-reason').value;

      // 作業時間計算
      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);
      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }
      const totalMinutes = (end - start) / (1000 * 60);
      const netMinutes = totalMinutes - breakTime;

      // 作業記録更新
      const updateData = {
        作業開始時刻: new Date(`${selectedRecord.作業日.split('T')[0]} ${startTime}`).toISOString(),
        作業終了時刻: new Date(`${selectedRecord.作業日.split('T')[0]} ${endTime}`).toISOString(),
        作業時間: Math.round(netMinutes),
        作業内容: workDetail,
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(1, recordId, updateData);

      if (updated) {
        // 異常値検出ログ作成（必要に応じて）
        if (totalMinutes > 12 * 60) {
          await window.aivicApi.save(4, {
            検出対象テーブル: '作業記録',
            検出対象レコードID: recordId,
            ユーザーID: selectedRecord.作業員ID,
            異常値種別: '長時間作業',
            検出項目: '作業時間',
            検出値: `${Math.round(totalMinutes)}分`,
            閾値: '720分',
            重要度: '高',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        alert('工数修正が完了しました。');
        window.showScreen("scr-1778907367889");
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存に失敗しました。');
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // DOM要素の取得
  const startDateInput = container.querySelector('#start-date');
  const endDateInput = container.querySelector('#end-date');
  const outputFormatSelect = container.querySelector('#output-format');
  const workerSelect = container.querySelector('#worker-select');
  const taskSelect = container.querySelector('#task-select');
  const locationSelect = container.querySelector('#location-select');
  const includeAnomalyCheck = container.querySelector('#include-anomaly');
  const includeInterruptionCheck = container.querySelector('#include-interruption');
  const errorMessage = container.querySelector('#error-message');
  const previewSection = container.querySelector('#preview-section');
  const previewContent = container.querySelector('#preview-content');
  const dataCount = container.querySelector('#data-count');
  const processingIndicator = container.querySelector('#processing-indicator');
  const saveDialog = container.querySelector('#save-dialog');
  const conditionNameInput = container.querySelector('#condition-name');

  // 初期データの設定
  function initializeSelects() {
    // 作業員データの設定（ユーザーテーブル）
    const users = tables[0]?.records || [];
    users.forEach(user => {
      if (user.有効フラグ) {
        const option = document.createElement('option');
        option.value = user.ユーザーID;
        option.textContent = user.氏名;
        workerSelect.appendChild(option);
      }
    });

    // 作業項目データの設定（作業項目マスタ）
    const workItems = tables[3]?.records || [];
    workItems.forEach(item => {
      if (item.有効フラグ) {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = item.作業項目名;
        taskSelect.appendChild(option);
      }
    });

    // 作業場所データの設定（作業記録から抽出）
    const workRecords = tables[1]?.records || [];
    const locations = [...new Set(workRecords.map(record => record.作業場所).filter(Boolean))];
    locations.forEach(location => {
      const option = document.createElement('option');
      option.value = location;
      option.textContent = location;
      locationSelect.appendChild(option);
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateConditions() {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const outputFormat = outputFormatSelect.value;
    const selectedWorkers = Array.from(workerSelect.selectedOptions).map(opt => opt.value);

    if (!startDate || !endDate) {
      showError('抽出期間（開始日・終了日）を指定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    return true;
  }

  // プレビュー表示
  function showPreview() {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const outputFormat = outputFormatSelect.value;
    const selectedWorkers = Array.from(workerSelect.selectedOptions);
    const selectedTasks = Array.from(taskSelect.selectedOptions);
    const location = locationSelect.value;
    const includeAnomaly = includeAnomalyCheck.checked;
    const includeInterruption = includeInterruptionCheck.checked;

    let previewText = '';

    if (startDate && endDate) {
      previewText += `期間: ${startDate} ～ ${endDate}<br>`;
    }

    if (selectedWorkers.length > 0) {
      const workerNames = selectedWorkers.map(opt => opt.textContent).join(', ');
      previewText += `作業員: ${workerNames}<br>`;
    }

    if (selectedTasks.length > 0) {
      const taskNames = selectedTasks.map(opt => opt.textContent).join(', ');
      previewText += `作業項目: ${taskNames}<br>`;
    }

    if (location) {
      previewText += `作業場所: ${location}<br>`;
    }

    if (outputFormat) {
      previewText += `出力形式: ${outputFormat.toUpperCase()}<br>`;
    }

    previewText += `異常値データ: ${includeAnomaly ? '含む' : '除外'}<br>`;
    previewText += `中断記録: ${includeInterruption ? '含む' : '除外'}`;

    previewContent.innerHTML = previewText;

    // データ件数の計算（模擬）
    const workRecords = tables[1]?.records || [];
    let filteredCount = workRecords.length;

    if (startDate && endDate) {
      filteredCount = workRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate >= new Date(startDate) && recordDate <= new Date(endDate);
      }).length;
    }

    dataCount.textContent = `予想データ件数: ${filteredCount}件`;
    previewSection.style.display = 'block';
  }

  // データ抽出実行
  async function executeExtraction() {
    if (!validateConditions()) return;

    processingIndicator.style.display = 'inline';

    try {
      // 実際の抽出処理をシミュレート
      await new Promise(resolve => setTimeout(resolve, 2000));

      const outputFormat = outputFormatSelect.value;
      const startDate = startDateInput.value;
      const endDate = endDateInput.value;

      // 作業記録データを取得
      const workRecords = await window.aivicApi.list(1) || [];

      // フィルタリング
      let filteredData = workRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate >= new Date(startDate) && recordDate <= new Date(endDate);
      });

      // 異常値除外
      if (!includeAnomalyCheck.checked) {
        filteredData = filteredData.filter(record => {
          // 24時間（1440分）を超える作業時間を異常値とする
          return !record.作業時間 || record.作業時間 <= 1440;
        });
      }

      // 中断記録の処理
      if (includeInterruptionCheck.checked) {
        const interruptionRecords = await window.aivicApi.list(2) || [];
        // 中断記録を含める処理（実装簡略化）
      }

      // CSV/Excel出力
      if (outputFormat === 'csv') {
        downloadCSV(filteredData);
      } else if (outputFormat === 'excel') {
        downloadExcel(filteredData);
      }

    } catch (error) {
      if (filteredData.length > 10000) {
        showError('大量データ抽出処理がタイムアウトしました。条件を絞り込んでください。');
      } else {
        showError('データ抽出中にエラーが発生しました');
      }
    } finally {
      processingIndicator.style.display = 'none';
    }
  }

  // CSV ダウンロード
  function downloadCSV(data) {
    if (data.length === 0) {
      showError('該当するデータが見つかりませんでした');
      return;
    }

    const headers = ['作業日', '作業員', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(record => [
        record.作業日 || '',
        record.作業員名 || '',
        record.作業開始時刻 || '',
        record.作業終了時刻 || '',
        record.作業時間 || '',
        record.プロジェクト名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // Excel ダウンロード（CSV形式で代用）
  function downloadExcel(data) {
    if (data.length === 0) {
      showError('該当するデータが見つかりませんでした');
      return;
    }

    // 簡易的にCSV形式でExcelファイルとして出力
    const headers = ['作業日', '作業員', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(record => [
        record.作業日 || '',
        record.作業員名 || '',
        record.作業開始時刻 || '',
        record.作業終了時刻 || '',
        record.作業時間 || '',
        record.プロジェクト名 || '',
        record.作業場所 || '',
        record.作業種別 || '',
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'application/vnd.ms-excel;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.xlsx`;
    link.click();
  }

  // 条件クリア
  function clearConditions() {
    startDateInput.value = '';
    endDateInput.value = '';
    outputFormatSelect.value = '';
    workerSelect.selectedIndex = -1;
    taskSelect.selectedIndex = -1;
    locationSelect.value = '';
    includeAnomalyCheck.checked = false;
    includeInterruptionCheck.checked = false;
    previewSection.style.display = 'none';
    errorMessage.style.display = 'none';
  }

  // 条件保存
  function saveCondition() {
    const conditionName = conditionNameInput.value.trim();
    if (!conditionName) {
      showError('条件名を入力してください');
      return;
    }

    const condition = {
      name: conditionName,
      startDate: startDateInput.value,
      endDate: endDateInput.value,
      outputFormat: outputFormatSelect.value,
      workers: Array.from(workerSelect.selectedOptions).map(opt => opt.value),
      tasks: Array.from(taskSelect.selectedOptions).map(opt => opt.value),
      location: locationSelect.value,
      includeAnomaly: includeAnomalyCheck.checked,
      includeInterruption: includeInterruptionCheck.checked,
      createdAt: new Date().toISOString()
    };

    // ローカルストレージに保存
    const savedConditions = JSON.parse(localStorage.getItem('extractionConditions') || '[]');
    savedConditions.push(condition);
    localStorage.setItem('extractionConditions', JSON.stringify(savedConditions));

    saveDialog.style.display = 'none';
    conditionNameInput.value = '';

    // 成功メッセージ表示
    const successMsg = container.querySelector('#error-message');
    successMsg.style.background = 'rgba(34, 197, 94, 0.1)';
    successMsg.style.borderColor = 'rgba(34, 197, 94, 0.3)';
    successMsg.style.color = '#86efac';
    successMsg.textContent = '条件が保存されました';
    successMsg.style.display = 'block';
    setTimeout(() => {
      successMsg.style.display = 'none';
